var PAUS = [{"no":1,"nama":"St. Petrus","masa":"±30 – 64/67","lahir":"±1 M, Betsaida, Galilea (tanggal pasti tidak diketahui)","bio":"Nelayan Galilea bernama Simon, dipanggil Yesus menjadi \"Petrus\" — batu karang tempat Gereja dibangun. Ia memimpin Gereja perdana di Yerusalem, Antiokhia, lalu Roma.","kisah":"Menyangkal Yesus tiga kali, namun bertobat dan diampuni; wafat sebagai martir di Roma — disalibkan terbalik karena merasa tak layak mati seperti Gurunya.","foto":"https://upload.wikimedia.org/wikipedia/commons/7/75/St._Peter_%28portrayed_as_a_Roman_consul%29.jpg"},{"no":2,"nama":"St. Linus","masa":"±67 – 76","lahir":"di Volterra, Tuscania (tanggal tidak diketahui)","bio":"Penerus Petrus; namanya disebut dalam 2 Timotius 4:21. Memimpin Gereja Roma pada masa penganiayaan Kaisar Nero.","kisah":"Sedikit yang diketahui tentangnya, namun namanya tercatat dalam Kanon Misa Roma — kesaksian awal suksesi apostolik.","foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/St._Linus%2C_Pope_Met_DP891130.jpg/960px-St._Linus%2C_Pope_Met_DP891130.jpg"},{"bio":"Paus ketiga dan Paus Yunani pertama, yang memimpin Gereja Roma pada akhir abad pertama.","kisah":"Ia pernah keliru dipecah menjadi dua orang dalam daftar-daftar lama, Kletus dan Anakletus.","lahir":"Athena, Akhaya, Kekaisaran Romawi","masa":"±76–±88","nama":"St. Anakletus","no":3,"foto":null},{"no":4,"nama":"St. Klemens I","masa":"±88 – 97","lahir":"±35 M, Roma","bio":"Penulis Surat kepada umat Korintus — dokumen Kristen tertua di luar Perjanjian Baru — yang menegakkan otoritas para uskup.","kisah":"Menurut tradisi, ia dibuang ke Krimea dan wafat sebagai martir dengan jangkar diikatkan di lehernya.","foto":"https://upload.wikimedia.org/wikipedia/commons/d/d5/Clemens_Romanus.jpg"},{"bio":"Seorang Yahudi Helenis kelahiran Betlehem yang memimpin Gereja Roma pada pergantian abad pertama ke abad kedua.","kisah":"Konon ia membagi kota Roma menjadi paroki-paroki dan menugaskan seorang imam untuk tiap paroki.","lahir":"Betlehem, Yudea, Kekaisaran Romawi","masa":"±97–±105","nama":"St. Evaristus","no":5,"foto":null},{"bio":"Paus Roma yang memimpin Gereja pada masa Kaisar Trajanus, ketika umat Kristen masih mengalami penganiayaan.","kisah":"Ia memprakarsai kebiasaan memberkati rumah dengan air suci.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"±105–±115","nama":"St. Aleksander I","no":6,"foto":null},{"bio":"Orang Roma keturunan Yunani yang memimpin Gereja selama sekitar sepuluh tahun.","kisah":"Pestanya dirayakan pada 6 April.","lahir":"±42, Roma, Italia, Kekaisaran Romawi","masa":"±115–±125","nama":"St. Sistus I","no":7,"foto":null},{"bio":"Orang Roma keturunan Yunani yang disebut Bapa Gereja St. Ireneus sebagai seorang martir besar.","kisah":"Kemartirannya adalah kesaksian kemartiran Paus paling awal setelah St. Petrus.","lahir":"Terra Nova, Italia, Kekaisaran Romawi","masa":"±125–±136","nama":"St. Telesforus","no":8,"foto":null},{"bio":"Paus Yunani kelahiran Athena yang memimpin Gereja Roma selama sekitar empat tahun.","kisah":"Menurut tradisi ia wafat sebagai martir; pestanya dirayakan pada 11 Januari.","lahir":"Athena, Akhaya, Kekaisaran Romawi","masa":"±136–±140","nama":"St. Higinus","no":9,"foto":null},{"bio":"Saudara Hermas, penulis karya kuno Gembala Hermas, yang menetapkan Paskah hanya dirayakan pada hari Minggu.","kisah":"Ia wafat sebagai martir dengan pedang; pestanya dirayakan pada 11 Juli.","lahir":"Aquileia, Italia, Kekaisaran Romawi","masa":"±140–±155","nama":"St. Pius I","no":10,"foto":null},{"bio":"Paus Suriah pertama, seorang Suriah yang dihelenisasi, yang memimpin Gereja Roma selama sekitar sebelas tahun.","kisah":"Ia menetapkan bahwa imam tidak boleh berambut panjang.","lahir":"Emesa, Suriah, Kekaisaran Romawi","masa":"±155–166/167","nama":"St. Anisetus","no":11,"foto":null},{"bio":"Ia menyatakan perkawinan sah sebagai sakramen yang diberkati oleh imam dan meresmikan Paskah sebagai perayaan tahunan di Roma.","kisah":"Menurut tradisi ia wafat sebagai martir; pestanya dirayakan pada 22 April.","lahir":"Fundi, Italia, Kekaisaran Romawi","masa":"166/167–174/175","nama":"St. Soter","no":12,"foto":null},{"bio":"Paus Yunani yang memimpin Gereja Roma selama sekitar empat belas tahun pada akhir abad kedua.","kisah":"Menurut tradisi ia wafat sebagai martir; pestanya dirayakan pada 6 Mei.","lahir":"Nikopolis, Epirus, Kekaisaran Romawi","masa":"174/175–189","nama":"St. Eleuterius","no":13,"foto":null},{"bio":"Paus pertama yang lahir di benua Afrika, seorang Berber Romawi yang mengekskomunikasi Theodotus dari Bizantium.","kisah":"Ia terlibat dalam kontroversi Quartodeciman soal tanggal perayaan Paskah.","lahir":"Afrika, Kekaisaran Romawi","masa":"189–198/199","nama":"St. Viktor I","no":14,"foto":null},{"bio":"Ia memerangi bidah adopsi para pengikut Theodotus dari Bizantium selama masa jabatan yang panjang, sekitar delapan belas tahun.","kisah":"Meski tidak dibunuh secara fisik, ia disebut martir karena penderitaan yang ditanggungnya.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"198/199–217","nama":"St. Zefirinus","no":15,"foto":null},{"bio":"Seorang mantan budak yang menjadi Paus dan wafat sebagai martir pada tahun 222.","kisah":"Katakomba Kalistus di Roma, tempat pemakaman para Paus awal, dinamai menurut namanya.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"218–222","nama":"St. Kalistus I","no":16,"foto":null},{"bio":"Pemilihannya pada tahun 222 adalah salah satu tanggal pasti pertama dalam sejarah kepausan.","kisah":"Pestanya dirayakan pada 25 Mei.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"222–230","nama":"St. Urbanus I","no":17,"foto":null},{"bio":"Paus pertama yang mengundurkan diri dari jabatannya, karena ia dibuang ke Sardinia oleh Kaisar Maximinus Thrax.","kisah":"Tanggal pembuangannya, 28 September 235, adalah tanggal pasti paling awal dalam sejarah Paus.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"230–235","nama":"St. Pontianus","no":18,"foto":null},{"bio":"Orang Roma keturunan Yunani yang masa jabatannya hanya 43 hari, salah satu yang terpendek dalam sejarah.","kisah":"Pestanya dirayakan pada 3 Januari.","lahir":"Petelia, Italia, Kekaisaran Romawi","masa":"235–236","nama":"St. Anterus","no":19,"foto":null},{"bio":"Ia membagi komunitas Roma menjadi tujuh distrik, masing-masing diawasi oleh seorang diakon.","kisah":"Ia wafat sebagai martir pada penganiayaan Kaisar Decius; pestanya dirayakan pada 20 Januari.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"236–250","nama":"St. Fabianus","no":20,"foto":null},{"bio":"Ia menghadapi skisma Novatianus soal penerimaan kembali umat yang murtad pada masa penganiayaan.","kisah":"Ia wafat sebagai martir karena penderitaan berat; pestanya dirayakan pada 16 September.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"251–253","nama":"St. Kornelius","no":21,"foto":null},{"bio":"Paus Roma yang masa jabatannya singkat, kurang dari satu tahun.","kisah":"Pestanya dirayakan pada 5 Maret.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"253–254","nama":"St. Lusius I","no":22,"foto":null},{"bio":"Ia berselisih dengan St. Siprianus dari Kartago soal pembaptisan ulang kaum bidah dan wafat sebagai martir dengan dipenggal.","kisah":"Pestanya dirayakan pada 2 Agustus.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"254–257","nama":"St. Stefanus I","no":23,"foto":null},{"bio":"Ia wafat sebagai martir dengan dipenggal pada penganiayaan Kaisar Valerianus, hanya setahun setelah terpilih.","kisah":"Diakonnya, St. Laurensius, wafat sebagai martir hanya beberapa hari sesudahnya.","lahir":"Athena, Akhaya, Kekaisaran Romawi","masa":"257–258","nama":"St. Sistus II","no":24,"foto":null},{"bio":"Ia menata kembali Gereja Roma setelah penganiayaan Kaisar Valerianus dan memimpin selama hampir sepuluh tahun.","kisah":"Pestanya dirayakan pada 26 Desember.","lahir":"Terra Nova, Italia, Kekaisaran Romawi","masa":"259–268","nama":"St. Dionisius","no":25,"foto":null},{"bio":"Paus Roma yang memimpin Gereja selama hampir enam tahun pada masa damai yang relatif bagi umat Kristen.","kisah":"Pestanya dirayakan pada 30 Desember.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"269–274","nama":"St. Feliks I","no":26,"foto":null},{"bio":"Paus Roma yang memimpin Gereja selama hampir sembilan tahun pada akhir abad ketiga.","kisah":"Menurut tradisi, ia menguburkan para martir dengan tangannya sendiri; pestanya pada 8 Desember.","lahir":"Luna, Italia, Kekaisaran Romawi","masa":"275–283","nama":"St. Eutikianus","no":27,"foto":null},{"bio":"Paus kelahiran Salona di Dalmasia (Kroasia modern) yang memimpin Gereja selama lebih dari dua belas tahun.","kisah":"Menurut legenda ia wafat sebagai martir dengan dipenggal; pestanya pada 22 April.","lahir":"Salona, Dalmasia, Kekaisaran Romawi","masa":"283–296","nama":"St. Kaius","no":28,"foto":null},{"bio":"Paus terakhir sebelum penganiayaan besar Kaisar Diokletianus; ia wafat pada tahun 304, di awal penganiayaan itu.","kisah":"Pestanya dirayakan pada 26 April.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"296–304","nama":"St. Marselinus","no":29,"foto":null},{"bio":"Ia dipilih setelah takhta kepausan kosong hampir empat tahun akibat penganiayaan, lalu dibuang oleh Kaisar Maxentius.","kisah":"Ia wafat di pengasingan; pestanya dirayakan pada 16 Januari.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"308–309","nama":"St. Marselus I","no":30,"foto":null},{"bio":"Orang Roma keturunan Yunani yang juga dibuang oleh Kaisar Maxentius dan wafat di pengasingan.","kisah":"Pestanya dirayakan pada 17 Agustus.","lahir":"Akhaya, Kekaisaran Romawi","masa":"309–310","nama":"St. Eusebius","no":31,"foto":null},{"bio":"Paus pertama setelah penganiayaan terhadap umat Kristen berakhir lewat Maklumat Milan (313) yang dikeluarkan Kaisar Konstantinus I.","kisah":"Ia memimpin Konsili Lateran tahun 313.","lahir":"Afrika, Kekaisaran Romawi","masa":"311–314","nama":"St. Miltiades","no":32,"foto":null},{"bio":"Paus pada Konsili Nicea I (325), konsili ekumenis pertama; di masanya dibangun Basilika St. Yohanes Lateran dan Basilika St. Petrus yang lama.","kisah":"Pestanya dirayakan pada 31 Desember, malam pergantian tahun.","lahir":"Sant'Angelo a Scala, Apulia, Kekaisaran Romawi","masa":"314–335","nama":"St. Silvester I","no":33,"foto":null},{"bio":"Ia menghimpun kisah para martir dan uskup sebelumnya, dan mungkin mendirikan Gereja San Marco di Roma.","kisah":"Pestanya dirayakan pada 7 Oktober.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"336","nama":"St. Markus","no":34,"foto":null},{"bio":"Ia terlibat dalam kontroversi Arianisme dan membela St. Athanasius dari Aleksandria.","kisah":"Pestanya dirayakan pada 12 April.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"337–352","nama":"St. Yulius I","no":35,"foto":null},{"bio":"Ia dibuang oleh Kaisar Constantius II yang condong ke Arianisme dan kemudian tunduk kepadanya; ia adalah Paus pertama yang tidak dikanonisasi oleh Gereja Latin.","kisah":"Ia dihormati sebagai santo di Gereja Timur, dengan pesta pada 27 Agustus.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"352–366","nama":"Paus Liberius","no":36,"foto":null},{"bio":"Paus pertama dari wilayah Portugal modern dan pelindung St. Hieronimus, yang ia tugaskan menerjemahkan Alkitab ke dalam bahasa Latin (Vulgata).","kisah":"Ia menjadi Paus pada Konsili Konstantinopel I (381), konsili ekumenis kedua.","lahir":"±305, Egitania, Lusitania (Portugal) atau Roma","masa":"366–384","nama":"St. Damasus I","no":37,"foto":null},{"bio":"Surat-suratnya adalah teks dekret kepausan tertua yang masih ada, membahas disiplin Gereja seperti pembaptisan, tahbisan, dan tobat.","kisah":"Dekretnya tahun 386 tentang selibat imam adalah dekret pertama tentang hal itu.","lahir":"±334, Roma, Italia, Kekaisaran Romawi","masa":"384–399","nama":"St. Sirisius","no":38,"foto":null},{"bio":"Ia memerintahkan para imam untuk berdiri dan menundukkan kepala saat membaca Injil.","kisah":"Pestanya dirayakan pada 19 Desember.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"399–401","nama":"St. Anastasius I","no":39,"foto":null},{"bio":"Pada masanya, Roma dijarah oleh bangsa Visigoth di bawah Raja Alarik I pada tahun 410.","kisah":"Pestanya dirayakan pada 12 Maret.","lahir":"Albanum, Latium, Kekaisaran Romawi","masa":"401–417","nama":"St. Inosensius I","no":40,"foto":null},{"bio":"Orang Roma keturunan Yunani yang memimpin Gereja selama kurang dari dua tahun.","kisah":"Pestanya dirayakan pada 27 Desember.","lahir":"Messurga, Lukania, Kekaisaran Romawi","masa":"417–418","nama":"St. Zosimus","no":41,"foto":null},{"bio":"Ia terpilih di tengah perselisihan dengan antipaus Eulalius, dan Kaisar Honorius akhirnya mendukungnya.","kisah":"Pestanya dirayakan pada 25 Oktober.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"418–422","nama":"St. Bonifasius I","no":42,"foto":null},{"bio":"Paus pada Konsili Efesus (431), konsili ekumenis ketiga, yang menyatakan Maria sebagai Bunda Allah (Theotokos).","kisah":"Pestanya dirayakan pada 27 Juli.","lahir":"Kampania, Kekaisaran Romawi","masa":"422–432","nama":"St. Selestinus I","no":43,"foto":null},{"bio":"Ia membangun dan memperindah gereja-gereja di Roma, termasuk Basilika Santa Maria Maggiore.","kisah":"Pestanya dirayakan pada 28 Maret.","lahir":"Roma, Italia, Kekaisaran Romawi","masa":"432–440","nama":"St. Sistus III","no":44,"foto":null},{"no":45,"nama":"St. Leo Agung","masa":"440 – 461","lahir":"±400, Tuscania, Italia","bio":"Doktor Gereja; menegakkan ajaran dua kodrat Kristus (Konsili Kalsedon 451) dan melindungi Roma dari serbuan bangsa Hun.","kisah":"Legenda mengisahkan ia berhadapan langsung dengan Attila sang Hun dan membujuknya mundur dari Italia.","foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Herrera_mozo_San_Le%C3%B3n_magno_Lienzo._%C3%93valo._164_x_105_cm._Museo_del_Prado.png/960px-Herrera_mozo_San_Le%C3%B3n_magno_Lienzo._%C3%93valo._164_x_105_cm._Museo_del_Prado.png"},{"bio":"Ia melanjutkan karya Leo Agung dengan membangun gereja dan biara di Roma serta menegakkan disiplin Gereja.","kisah":"Pestanya dirayakan pada 28 Februari.","lahir":"Sardinia, Italia, Kekaisaran Romawi Barat","masa":"461–468","nama":"St. Hilarius","no":46,"foto":null},{"bio":"Ia menjadi Paus saat Kekaisaran Romawi Barat runtuh pada tahun 476 dan Roma dikuasai Raja Odoacer.","kisah":"Pestanya dirayakan pada 10 Maret.","lahir":"Tibur (Tivoli), Italia","masa":"468–483","nama":"St. Simplicius","no":47,"foto":null},{"bio":"Kakek buyut St. Gregorius Agung yang kadang disebut Feliks II karena antipaus Feliks II tidak dihitung.","kisah":"Pestanya dirayakan pada 1 Maret.","lahir":"Roma, Italia, Kerajaan Odoacer","masa":"483–492","nama":"St. Feliks III","no":48,"foto":null},{"bio":"Paus terakhir yang lahir di benua Afrika dan Paus pertama yang disebut Vicarius Christi (Wakil Kristus).","kisah":"Pestanya dirayakan pada 21 November.","lahir":"Mons Ferratus, Afrika, Kerajaan Odoacer","masa":"492–496","nama":"St. Gelasius I","no":49,"foto":null},{"bio":"Ia berusaha mengakhiri skisma Akasius, tetapi upayanya justru memicu skisma Laurentian.","kisah":"Ia adalah Paus pertama yang tidak dikanonisasi baik oleh Gereja Latin maupun Gereja Timur.","lahir":"Roma, Italia, Kerajaan Ostrogoth","masa":"496–498","nama":"Paus Anastasius II","no":50,"foto":null},{"bio":"Ia terpilih pada hari yang sama dengan antipaus Laurensius, dan Raja Theodoric akhirnya memihak kepadanya.","kisah":"Pestanya dirayakan pada 19 Juli.","lahir":"Sardinia, Italia, Kerajaan Ostrogoth","masa":"498–514","nama":"St. Simakhus","no":51,"foto":null},{"bio":"Ayah dari Paus Silverius; ia mengakhiri skisma Akasius pada tahun 519 lewat Formula Hormisdas.","kisah":"Pestanya dirayakan pada 6 Agustus.","lahir":"±450, Frusino, Italia, Kerajaan Ostrogoth","masa":"514–523","nama":"St. Hormisdas","no":52,"foto":null},{"bio":"Ia ditangkap oleh Raja Theodoric karena dicurigai bersekongkol dengan Kaisar Yustinus.","kisah":"Ia wafat di penjara Ravenna karena penelantaran dan perlakuan buruk; pestanya pada 18 Mei.","lahir":"Sena Iulia (Siena), Italia, Kerajaan Ostrogoth","masa":"523–526","nama":"St. Yohanes I","no":53,"foto":null},{"bio":"Ia membangun Gereja Santi Cosma e Damiano di Roma dan kadang disebut Feliks III.","kisah":"Pestanya dirayakan pada 30 Januari.","lahir":"±490, Samnium, Kerajaan Ostrogoth","masa":"526–530","nama":"St. Feliks IV","no":54,"foto":null},{"bio":"Seorang Ostrogoth dan Paus Jermanik pertama dalam sejarah.","kisah":"Ia mengubah penomoran tahun kalender Julian dari Anno Martyrum menjadi Anno Domini.","lahir":"Italia (Kerajaan Ostrogoth)","masa":"530–532","nama":"Paus Bonifasius II","no":55,"foto":null},{"bio":"Paus pertama yang tidak memakai nama pribadinya, karena nama lahirnya Mercurius dikaitkan dengan dewa Romawi Merkurius.","kisah":"Ia memilih nama kepausan Yohanes karena nama lahirnya adalah nama dewa.","lahir":"±475, Roma, Kekaisaran Romawi Barat","masa":"533–535","nama":"Paus Yohanes II","no":56,"foto":null},{"bio":"Masa jabatannya kurang dari setahun; ia wafat di Konstantinopel saat menjalankan misi diplomatik kepada Kaisar Yustinianus.","kisah":"Pestanya dirayakan pada 22 April dan 20 September.","lahir":"±490, Roma, Kerajaan Ostrogoth","masa":"535–536","nama":"St. Agapitus I","no":57,"foto":null},{"bio":"Putra Paus Hormisdas yang dibuang dari Roma dan wafat di pengasingan.","kisah":"Pestanya dirayakan pada 20 Juni.","lahir":"Cicanum, Italia, Kerajaan Ostrogoth","masa":"536–537","nama":"St. Silverius","no":58,"foto":null},{"bio":"Paus pada Konsili Konstantinopel II (553), konsili ekumenis kelima yang diakui Gereja Katolik dan Ortodoks Timur.","kisah":"Masa jabatannya yang panjang diwarnai perang Goth dan tekanan Kaisar Yustinianus.","lahir":"±497, Roma, Kerajaan Ostrogoth","masa":"537–555","nama":"Paus Vigilius","no":59,"foto":null},{"bio":"Ia dikreditkan membangun Basilika Santi Apostoli di Roma.","kisah":"Ia membangun kembali Roma setelah perang Goth yang menghancurkan kota itu.","lahir":"±500, Roma, Kerajaan Ostrogoth","masa":"556–561","nama":"Paus Pelagius I","no":60,"foto":null},{"bio":"Paus kedua yang tidak memakai nama pribadinya, Catelinus, saat menjadi Paus.","kisah":"Masa jabatannya diwarnai invasi bangsa Lombard ke Italia pada tahun 568.","lahir":"Roma, Kerajaan Ostrogoth","masa":"561–574","nama":"Paus Yohanes III","no":61,"foto":null},{"bio":"Ia memimpin Gereja di tengah invasi bangsa Lombard dan kelaparan yang melanda Roma.","kisah":"Ia berjuang memberi makan penduduk Roma saat kota dilanda paceklik.","lahir":"Roma, Kerajaan Ostrogoth","masa":"575–579","nama":"Paus Benediktus I","no":62,"foto":null},{"bio":"Seorang Ostrogoth yang diromanisasi; ia memerintahkan pembangunan Basilika San Lorenzo fuori le Mura.","kisah":"Ia wafat karena wabah pes yang melanda Roma pada tahun 590.","lahir":"Roma, Kerajaan Ostrogoth","masa":"579–590","nama":"Paus Pelagius II","no":63,"foto":null},{"no":64,"nama":"St. Gregorius Agung","masa":"590 – 604","lahir":"±540, Roma","bio":"Dari prefek kota menjadi biarawan lalu Paus; pembaru liturgi (kidung Gregorian) dan pengutus misi ke Inggris.","kisah":"Menyebut dirinya \"servus servorum Dei\" — hamba dari para hamba Allah — gelar yang dipakai semua Paus sesudahnya.","foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Gregory_the_Great_with_the_Holy_Spirit.jpg/960px-Gregory_the_Great_with_the_Holy_Spirit.jpg"},{"bio":"Ia adalah Paus pertama dalam dua abad masa ketika para Paus Roma dikendalikan oleh Kekaisaran Romawi Timur.","kisah":"Menurut tradisi, ia dikritik karena menjual gandum saat kelaparan, berbeda dengan kemurahan Gregorius Agung.","lahir":"±530, Blera, Kekaisaran Romawi Timur","masa":"604–606","nama":"Paus Sabinianus","no":65,"foto":null},{"bio":"Masa jabatannya hanya 266 hari; ia melarang pembahasan soal pengganti Paus selagi Paus masih hidup.","kisah":"Ia memperoleh pengakuan Kaisar Fokas bahwa Roma adalah kepala semua Gereja.","lahir":"Roma, Kekaisaran Romawi Timur","masa":"607","nama":"Paus Bonifasius III","no":66,"foto":null},{"bio":"Seorang biarawan Benediktin dan Paus pertama yang memakai nama yang sama dengan pendahulunya langsung.","kisah":"Ia mengubah Pantheon Roma menjadi gereja Santa Maria ad Martyres pada tahun 609.","lahir":"±550, Marsica, Kekaisaran Romawi Timur","masa":"608–615","nama":"St. Bonifasius IV","no":67,"foto":null},{"bio":"Juga disebut Deusdedit; ia adalah Paus pertama yang memakai segel timah pada dokumen kepausan, cikal bakal bulla kepausan.","kisah":"Ia merawat para korban gempa dan wabah yang melanda Roma; pestanya pada 8 November.","lahir":"Roma, Kekaisaran Romawi Timur","masa":"615–618","nama":"St. Adeodatus I","no":68,"foto":null},{"bio":"Ia menetapkan gereja sebagai tempat perlindungan (suaka) bagi para pelarian.","kisah":"Ia mendukung misi St. Paulinus di Inggris.","lahir":"Neapolis (Napoli), Kekaisaran Romawi Timur","masa":"619–625","nama":"Paus Bonifasius V","no":69,"foto":null},{"bio":"Ia dinyatakan bidah dan dianatema oleh Konsili Konstantinopel III (680) karena sikapnya terhadap monotelitisme.","kisah":"Ia adalah satu-satunya Paus yang dianatema oleh sebuah konsili ekumenis.","lahir":"Ceperanum, Kampania, Kekaisaran Romawi Timur","masa":"625–638","nama":"Paus Honorius I","no":70,"foto":null},{"bio":"Masa jabatannya hanya 66 hari, dan pemilihannya tertunda hampir dua tahun menunggu pengesahan Kaisar.","kisah":"Ia menolak menandatangani Ekthesis Kaisar Heraklius yang mendukung monotelitisme.","lahir":"±585, Roma, Kekaisaran Romawi Timur","masa":"640","nama":"Paus Severinus","no":71,"foto":null},{"bio":"Berasal dari Dalmasia (Kroasia modern); ia menebus tawanan Slavia dan membangun kapel di Lateran.","kisah":"Ia mengutuk monotelitisme dalam sebuah sinode di Roma.","lahir":"±585, Iadera (Zadar), Dalmasia, Kekaisaran Romawi Timur","masa":"640–642","nama":"Paus Yohanes IV","no":72,"foto":null},{"bio":"Paus terakhir dari Palestina; ia merencanakan Konsili Lateran 649 tetapi wafat sebelum konsili itu dibuka.","kisah":"Ia mengekskomunikasi Patriark Paulus II dari Konstantinopel karena monotelitisme.","lahir":"Yerusalem, Kekaisaran Romawi Timur","masa":"642–649","nama":"Paus Teodorus I","no":73,"foto":null},{"bio":"Paus terakhir yang diakui sebagai martir; ia memimpin Konsili Lateran 649 yang mengutuk monotelitisme.","kisah":"Ia ditangkap atas perintah Kaisar Konstans II, dibuang ke Krimea dan wafat di sana; pestanya pada 12 November.","lahir":"±598, dekat Tuder (Todi), Umbria, Kekaisaran Romawi Timur","masa":"649–654","nama":"St. Martinus I","no":74,"foto":null},{"bio":"Ia dipilih saat Martinus I masih hidup dalam pembuangan, dan dikenal karena kelembutan serta kemurahan hatinya.","kisah":"Pestanya dirayakan pada 2 Juni.","lahir":"±615, Roma, Kekaisaran Romawi Timur","masa":"654–657","nama":"St. Eugenius I","no":75,"foto":null},{"bio":"Ia berusaha memperbaiki hubungan dengan Konstantinopel dan mendukung misi Gereja ke Inggris.","kisah":"Ia mengutus St. Theodorus dari Tarsus sebagai Uskup Agung Canterbury.","lahir":"±600, Signia, Kekaisaran Romawi Timur","masa":"657–672","nama":"St. Vitalianus","no":76,"foto":null},{"bio":"Seorang biarawan Benediktin; masa jabatannya banyak dipakai untuk memulihkan gereja-gereja yang rusak dan melawan monotelitisme.","kisah":"Ia dikenal murah hati kepada kaum miskin dan peziarah; gelar santonya masih diperdebatkan dan tidak tercantum dalam Martyrologium Romanum terbaru.","lahir":"±621, Roma, Kekaisaran Romawi Timur","masa":"672–676","nama":"Paus Adeodatus II","no":77,"foto":null},{"bio":"Masa jabatannya singkat; ia memulihkan gereja-gereja dan menegakkan ajaran yang benar melawan bidah.","kisah":"Ia menerima kembali Uskup Agung Ravenna yang sebelumnya memisahkan diri dari Roma.","lahir":"Roma, Kekaisaran Romawi Timur","masa":"676–678","nama":"Paus Donus","no":78,"foto":null},{"bio":"Paus pada Konsili Konstantinopel III (680), konsili ekumenis keenam yang mengutuk monotelitisme.","kisah":"Menurut daftar Wikipedia, ia terpilih pada usia sekitar 101 tahun dan wafat pada usia sekitar 104 tahun.","lahir":"±577, Panormus (Palermo), Sisilia, Kekaisaran Romawi Timur","masa":"678–681","nama":"St. Agato","no":79,"foto":null},{"bio":"Ia mengesahkan keputusan Konsili Konstantinopel III dan dikenal fasih berbahasa Yunani dan Latin serta mahir bermusik.","kisah":"Pestanya dirayakan pada 3 Juli.","lahir":"±611, Aydonum (Aidone), Sisilia, Kekaisaran Romawi Timur","masa":"682–683","nama":"St. Leo II","no":80,"foto":null},{"bio":"Ia memperoleh keputusan Kaisar agar pemilihan Paus tidak perlu lagi menunggu pengesahan dari Konstantinopel.","kisah":"Pestanya dirayakan pada 7 Mei.","lahir":"±635, Roma, Kekaisaran Romawi Timur","masa":"684–685","nama":"St. Benediktus II","no":81,"foto":null},{"bio":"Paus pertama dari Antiokhia yang masa jabatannya berlangsung sekitar satu tahun.","kisah":"Ia ditahbiskan tanpa menunggu pengesahan Kaisar, berkat dekret pendahulunya.","lahir":"±635, Antiokhia, Suriah, Kekaisaran Romawi Timur","masa":"685–686","nama":"Paus Yohanes V","no":82,"foto":null},{"bio":"Orang Yunani dari Trakia yang terpilih sebagai kompromi antara kubu militer dan kubu klerus Roma.","kisah":"Ia menerima misi St. Kilian, rasul Franconia.","lahir":"±630, Trakia, Kekaisaran Romawi Timur","masa":"686–687","nama":"Paus Konon","no":83,"foto":null},{"bio":"Seorang Suriah yang dihelenisasi; ia memperkenalkan nyanyian Anak Domba Allah (Agnus Dei) dalam Misa.","kisah":"Ia menolak mengakui kanon-kanon Konsili Quinisext yang bertentangan dengan praktik Roma.","lahir":"±650, Palermo, Sisilia, Kekaisaran Romawi Timur","masa":"687–701","nama":"St. Sergius I","no":84,"foto":null},{"bio":"Satu-satunya Paus yang berasal dari Asia Kecil.","kisah":"Ia menengahi konflik antara kaum Lombard dan Kekaisaran serta melindungi penduduk Roma.","lahir":"±655, Efesus, Kekaisaran Romawi Timur","masa":"701–705","nama":"Paus Yohanes VI","no":85,"foto":null},{"bio":"Paus kedua yang memakai nama yang sama dengan pendahulunya langsung; ia dikenal sebagai pelindung seni.","kisah":"Ia menghias Basilika St. Petrus dengan mosaik-mosaik yang indah.","lahir":"±650, Rossanum (Rossano), Kalabria, Kekaisaran Romawi Timur","masa":"705–707","nama":"Paus Yohanes VII","no":86,"foto":null},{"bio":"Paus pertama yang berasal dari negara Muslim; masa jabatannya hanya 20 hari karena ia sakit parah.","kisah":"Meski menderita encok berat, ia sempat memerintahkan perbaikan tembok kota Roma.","lahir":"Suriah, Kekhalifahan Rasyidin","masa":"708","nama":"Paus Sisinius","no":87,"foto":null},{"bio":"Paus kedua dari negara Muslim dan Paus terakhir yang mengunjungi Yunani saat menjabat, hingga Yohanes Paulus II pada tahun 2001.","kisah":"Ia mengunjungi Konstantinopel pada tahun 710–711 dan disambut meriah oleh Kaisar Yustinianus II.","lahir":"±664, Tirus, Kekhalifahan Umayyah","masa":"708–715","nama":"Paus Konstantinus","no":88,"foto":null},{"bio":"Ia mengadakan Sinode Roma (721) dan menentang ikonoklasme Kaisar Leo III yang melarang penghormatan gambar suci.","kisah":"Ia mendukung misi St. Bonifasius di Jerman; pestanya pada 11 Februari.","lahir":"±669, Roma, Kekaisaran Romawi Timur","masa":"715–731","nama":"St. Gregorius II","no":89,"foto":null},{"bio":"Paus terakhir dari Suriah dan Paus terakhir yang lahir di luar Eropa hingga Paus Fransiskus pada tahun 2013.","kisah":"Ia menentang ikonoklasme dan meminta bantuan Karel Martel melawan bangsa Lombard.","lahir":"Suriah, Kekhalifahan Umayyah","masa":"731–741","nama":"St. Gregorius III","no":90,"foto":null},{"no":91,"nama":"St. Zakarias","masa":"741–752","lahir":"±679, Santa Severina, Calabria","bio":"Paus asal Yunani yang memerintah selama 10 tahun dan membangun Gereja Santa Maria sopra Minerva di Roma.","kisah":"Ia menyetujui Pippin yang Pendek menjadi Raja Franka, membuka jalan bagi dinasti Karoling dan persekutuan Paus-Franka.","foto":null},{"no":92,"nama":"Paus Stefanus II","masa":"752–757","lahir":"±714, Roma","bio":"Paus yang meminta perlindungan Pippin yang Pendek dari bangsa Lombardia dan menerima Donasi Pippin, cikal bakal Negara Gereja.","kisah":"Donasi Pippin (756) memberinya wilayah di Italia tengah, awal mula kekuasaan duniawi para Paus.","foto":null},{"no":93,"nama":"St. Paulus I","masa":"757–767","lahir":"±700, Roma","bio":"Adik Paus Stefanus II yang melanjutkan kebijakannya, memperkuat hubungan dengan Franka dan menentang ekspansi Lombardia.","kisah":"Ia dikenal karena karya amalnya kepada para tawanan dan kaum miskin di Roma.","foto":null},{"no":94,"nama":"Paus Stefanus III","masa":"768–772","lahir":"±720, Sirakusa, Sisilia","bio":"Paus asal Sisilia yang mengadakan Konsili Lateran 769 untuk menertibkan tata cara pemilihan Paus.","kisah":"Konsili Lateran 769 menetapkan bahwa pemilihan Paus hanya boleh dilakukan oleh para kardinal.","foto":null},{"no":95,"nama":"Paus Adrianus I","masa":"772–795","lahir":"±700, Roma","bio":"Paus yang memerintah 23 tahun, salah satu yang terlama, dan sezaman dengan Karel Agung yang menaklukkan Kerajaan Lombardia atas permintaannya.","kisah":"Pada masanya berlangsung Konsili Nicea II (787) yang memulihkan penghormatan terhadap ikon.","foto":null},{"no":96,"nama":"St. Leo III","masa":"795–816","lahir":"Roma","bio":"Paus yang memahkotai Karel Agung sebagai Kaisar Romawi pada Hari Natal tahun 800, mengawali Kekaisaran Romawi Suci.","kisah":"Setelah diserang lawan-lawannya di Roma pada 799, ia melarikan diri ke Karel Agung dan kembali ke Roma dengan perlindungannya.","foto":null},{"no":97,"nama":"Paus Stefanus IV","masa":"816–817","lahir":"Roma","bio":"Paus yang memahkotai Louis yang Saleh sebagai kaisar di Reims pada tahun 816.","kisah":"Ia melakukan perjalanan ke Prancis untuk memahkotai Kaisar Louis yang Saleh, mempererat persekutuan dengan Franka.","foto":null},{"no":98,"nama":"St. Paskalis I","masa":"817–824","lahir":"Roma","bio":"Paus yang menemukan jasad St. Sesilia di Katakomba Kalisus dan membangun Basilika Santa Sesilia di Trastevere.","kisah":"Ia menghiasi Roma dengan gereja-gereja baru, termasuk Santa Maria in Domnica.","foto":null},{"no":99,"nama":"Paus Eugenius II","masa":"824–827","lahir":"Roma","bio":"Paus yang mengadakan sinode di Roma pada 826 untuk memperbaiki disiplin dan pendidikan para rohaniwan.","kisah":"Sinode Roma 826 mewajibkan adanya sekolah di katedral dan paroki untuk mendidik klerus.","foto":null},{"no":100,"nama":"Paus Valentinus","masa":"827","lahir":"Roma","bio":"Paus yang hanya memerintah selama 40 hari pada tahun 827.","kisah":"Ia wafat hanya sebulan lebih setelah terpilih, menjadikan masa jabatannya salah satu yang terpendek.","foto":null},{"no":101,"nama":"Paus Gregorius IV","masa":"827–844","lahir":"Roma","bio":"Paus yang membangun kembali atrium Basilika St. Petrus dan memindahkan jasad Gregorius I.","kisah":"Ia memperluas perayaan Hari Raya Semua Orang Kudus (1 November) ke seluruh Gereja Barat.","foto":null},{"no":102,"nama":"Paus Sergius II","masa":"844–847","lahir":"Roma","bio":"Paus yang memerintah saat Roma diserbu bangsa Saracen pada 846, yang menjarah Basilika St. Petrus dan St. Paulus.","kisah":"Penjarahan Saracen 846 mendorong pembangunan tembok pertahanan di sekeliling Vatikan.","foto":null},{"no":103,"nama":"St. Leo IV","masa":"847–855","lahir":"Roma","bio":"Paus Benediktin yang membangun Tembok Leonine untuk melindungi Vatikan dari serangan Saracen.","kisah":"Pada 849, armada gabungan Italia di bawah pimpinannya mengalahkan Saracen dalam Pertempuran Ostia.","foto":null},{"no":104,"nama":"Paus Benediktus III","masa":"855–858","lahir":"Roma","bio":"Paus yang memerintah singkat di tengah perselisihan dengan Antipaus Anastasius yang didukung Kaisar Lothair I.","kisah":"Ia tetap diakui sebagai Paus sah setelah Antipaus Anastasius ditolak oleh para rohaniwan Roma.","foto":null},{"no":105,"nama":"St. Nikolaus I","masa":"858–867","lahir":"±800, Roma","bio":"Dijuluki 'Nikolaus Agung', ia menegaskan otoritas Paus atas raja-raja dan mendorong kegiatan misionaris.","kisah":"Ia menolak perceraian Raja Lothair II dan membela St. Ignatius, Patriark Konstantinopel, dalam Skisma Fotius.","foto":null},{"no":106,"nama":"Paus Adrianus II","masa":"867–872","lahir":"±792, Roma","bio":"Paus pada masa Konsili Konstantinopel IV (869–870), konsili ekumenis kedelapan Gereja Katolik.","kisah":"Ia menerima St. Sirilus dan St. Metodius di Roma dan menyetujui penggunaan bahasa Slavia dalam liturgi.","foto":null},{"no":107,"nama":"Paus Yohanes VIII","masa":"872–882","lahir":"Roma","bio":"Paus yang berjuang melawan serangan Saracen di Italia dan Paus pertama yang dibunuh.","kisah":"Ia dibunuh pada 882, kemungkinan oleh anggota keluarganya sendiri yang mengincar harta Gereja.","foto":null},{"no":108,"nama":"Paus Marinus I","masa":"882–884","lahir":"±830, Gallese","bio":"Paus yang juga dikenal secara keliru sebagai Martinus II karena kesamaan nama.","kisah":"Ia menjaga hubungan baik dengan Gereja Timur dan mengutus utusan ke Konstantinopel.","foto":null},{"no":109,"nama":"St. Adrianus III","masa":"884–885","lahir":"Roma","bio":"Paus yang memerintah singkat dan dihormati sebagai santo; hari perayaannya 8 Juli.","kisah":"Ia wafat dalam perjalanan ke Jerman saat hendak menghadiri sidang Kekaisaran di Worms.","foto":null},{"no":110,"nama":"Paus Stefanus V","masa":"885–891","lahir":"Roma","bio":"Paus yang memerintah di tengah kekacauan politik Italia dan tekanan dari Kekaisaran Bizantium dan Franka.","kisah":"Ia mengadopsi Guy III dari Spoleto sebagai putra angkatnya dan memahkotainya sebagai kaisar.","foto":null},{"no":111,"nama":"Paus Formosus","masa":"891–896","lahir":"±816, Ostia","bio":"Paus yang setelah wafat diadili dalam Sinode Jenazah (897), ketika jasadnya digali dan didudukkan di kursi pengadilan.","kisah":"Sinode Jenazah membatalkan semua pentahbisannya, namun kemudian ia direhabilitasi dan dimakamkan kembali dengan hormat.","foto":null},{"no":112,"nama":"Paus Bonifasius VI","masa":"896","lahir":"Roma","bio":"Paus yang memerintah hanya 15 hari pada April 896.","kisah":"Masa jabatannya yang sangat singkat terjadi di tengah kekacauan politik setelah Sinode Jenazah.","foto":null},{"no":113,"nama":"Paus Stefanus VI","masa":"896–897","lahir":"Roma","bio":"Paus yang menyelenggarakan Sinode Jenazah yang terkenal kejam terhadap pendahulunya, Formosus.","kisah":"Beberapa bulan setelah Sinode Jenazah, ia ditangkap, dipenjarakan, dan dicekik oleh lawan-lawannya.","foto":null},{"no":114,"nama":"Paus Romanus","masa":"897","lahir":"Gallese","bio":"Paus yang memerintah singkat pada 897 dan menganulir keputusan-keputusan Sinode Jenazah.","kisah":"Ia membatalkan tindakan Stefanus VI terhadap Formosus dan mengembalikan kehormatan pendahulunya.","foto":null},{"no":115,"nama":"Paus Teodorus II","masa":"897","lahir":"±840, Roma","bio":"Paus keturunan Yunani yang hanya memerintah 19 hari pada Desember 897.","kisah":"Dalam masa jabatannya yang singkat, ia memulihkan para rohaniwan yang ditahbiskan Formosus dan menguburkan kembali jasadnya dengan hormat.","foto":null},{"no":116,"nama":"Paus Yohanes IX","masa":"898–900","lahir":"±825, Tivoli","bio":"Paus Benediktin yang mengadakan sinode untuk mengutuk Sinode Jenazah dan melarang pengadilan atas orang mati.","kisah":"Sinode Roma 898 melarang pengadilan terhadap jenazah dan mengakhiri era Sinode Jenazah.","foto":null},{"no":117,"nama":"Paus Benediktus IV","masa":"900–903","lahir":"±840, Roma","bio":"Paus yang memahkotai Louis III sebagai Kaisar Romawi Suci pada 901.","kisah":"Ia memerintah di masa sulit ketika kekuasaan Paus sangat bergantung pada bangsawan Roma.","foto":null},{"no":118,"nama":"Paus Leo V","masa":"903","lahir":"Ardea","bio":"Paus yang memerintah kurang dari setahun sebelum digulingkan dan dibunuh pada 903.","kisah":"Ia digulingkan oleh Antipaus Kristoforus dan wafat di penjara, kemungkinan dibunuh.","foto":null},{"no":119,"nama":"Paus Sergius III","masa":"904–911","lahir":"±860, Roma","bio":"Paus yang mengawali masa kelam Gereja yang disebut 'Saeculum obscurum' dan Paus pertama yang digambarkan memakai tiara.","kisah":"Ia memerintahkan pembangunan kembali Basilika Lateran yang rusak akibat gempa bumi.","foto":null},{"no":120,"nama":"Paus Anastasius III","masa":"911–913","lahir":"±865, Roma","bio":"Paus yang memerintah di awal 'Saeculum obscurum', masa ketika kepausan dikuasai bangsawan Roma.","kisah":"Sedikit yang diketahui tentang masa jabatannya, kecuali ia mendukung misi evangelisasi di kalangan bangsa Norman.","foto":null},{"no":121,"nama":"Paus Lando","masa":"913–914","lahir":"Sabina","bio":"Paus terakhir yang memakai nama takhta yang benar-benar baru hingga Paus Fransiskus pada 2013.","kisah":"Ia memerintah hanya tujuh bulan dan menjadi Paus terakhir dengan nama yang belum pernah dipakai sebelumnya selama lebih dari seribu tahun.","foto":null},{"no":122,"nama":"Paus Yohanes X","masa":"914–928","lahir":"Tossignano","bio":"Paus yang memimpin pasukan gabungan Italia mengalahkan Saracen di Pertempuran Garigliano (915).","kisah":"Kemenangan di Garigliano mengusir Saracen dari Italia tengah, tetapi ia kemudian digulingkan dan dibunuh oleh Marozia.","foto":null},{"no":123,"nama":"Paus Leo VI","masa":"928–929","lahir":"±880, Roma","bio":"Paus yang memerintah singkat pada 928–929 di bawah bayang-bayang kekuasaan Marozia di Roma.","kisah":"Ia wafat setelah delapan bulan memerintah, di tengah perebutan kekuasaan keluarga bangsawan Roma.","foto":null},{"no":124,"nama":"Paus Stefanus VII","masa":"929–931","lahir":"Roma","bio":"Paus yang memerintah pada 929–931 dan juga disebut Stefanus VIII dalam beberapa daftar lama.","kisah":"Masa jabatannya berlangsung di bawah dominasi Marozia, penguasa de facto Roma saat itu.","foto":null},{"no":125,"nama":"Paus Yohanes XI","masa":"931–935","lahir":"±910, Roma","bio":"Paus muda yang naik takhta pada usia sekitar 21 tahun, putra Marozia yang berkuasa di Roma.","kisah":"Ia memerintah di bawah bayang-bayang ibunya Marozia, hingga saudaranya Alberik II merebut kekuasaan di Roma.","foto":null},{"no":126,"nama":"Paus Leo VII","masa":"936–939","lahir":"Roma","bio":"Paus Benediktin yang dikenal saleh dan berupaya mereformasi kehidupan rohaniwan.","kisah":"Ia mengundang St. Odo dari Cluny ke Roma untuk memperbarui kehidupan biara di Italia.","foto":null},{"no":127,"nama":"Paus Stefanus VIII","masa":"939–942","lahir":"Roma","bio":"Paus yang memerintah pada 939–942 dan juga disebut Stefanus IX dalam beberapa daftar lama.","kisah":"Ia mendukung Kekaisaran Jerman dan berupaya menjaga perdamaian antara Roma dan Konstantinopel.","foto":null},{"no":128,"nama":"Paus Marinus II","masa":"942–946","lahir":"Roma","bio":"Paus yang juga dikenal secara keliru sebagai Martinus III karena kesamaan nama.","kisah":"Ia memperbaiki gereja-gereja Roma dan mendukung karya misi di kalangan bangsa Slavia.","foto":null},{"no":129,"nama":"Paus Agapitus II","masa":"946–955","lahir":"±911, Roma","bio":"Paus yang memerintah sembilan tahun dan menolak permintaan Otto I untuk campur tangan dalam urusan Gereja Prancis.","kisah":"Ia mengadakan sinode di Ingelheim (948) yang mengutuk pemberontakan terhadap Raja Louis IV dari Prancis.","foto":null},{"no":130,"nama":"Paus Yohanes XII","masa":"955–964","lahir":"±930–937, Roma","bio":"Paus muda yang memahkotai Otto I sebagai Kaisar Romawi Suci pada 962, tetapi kemudian digulingkan oleh Otto.","kisah":"Ia digulingkan oleh Otto I pada 963, lalu kembali ke Roma dan wafat pada 964, mengakhiri 'Saeculum obscurum'.","foto":null},{"no":131,"nama":"Paus Benediktus V","masa":"964","lahir":"Roma","bio":"Paus yang dipilih rakyat Roma untuk melawan Leo VIII, tetapi kemudian menerima pemecatannya demi perdamaian.","kisah":"Ia memerintah hanya sebulan sebelum menyerahkan takhta kepada Leo VIII dan wafat dalam pengasingan di Hamburg.","foto":null},{"no":132,"nama":"Paus Leo VIII","masa":"964–965","lahir":"±915, Roma","bio":"Paus yang diangkat oleh Kaisar Otto I sebagai antipaus, tetapi kemudian diakui sah setelah Benediktus V mengundurkan diri.","kisah":"Masa jabatannya 963–964 dianggap tidak sah, tetapi kepausannya setelah Juni 964 diakui oleh Gereja.","foto":null},{"no":133,"nama":"Paus Yohanes XIII","masa":"965–972","lahir":"Roma","bio":"Paus yang dijuluki 'Yang Baik' dan memperkenalkan tradisi pemberkatan lonceng gereja.","kisah":"Ia memahkotai Otto II sebagai kaisar dan membangun kembali kekuasaan Paus setelah masa kekacauan.","foto":null},{"no":134,"nama":"Paus Benediktus VI","masa":"973–974","lahir":"Roma","bio":"Paus yang digulingkan dan dibunuh pada 974 atas perintah Antipaus Bonifasius VII.","kisah":"Ia dipenjarakan di Kastil Sant'Angelo dan dicekik, salah satu Paus yang mati dibunuh.","foto":null},{"no":135,"nama":"Paus Benediktus VII","masa":"974–983","lahir":"Roma","bio":"Paus yang memerintah delapan tahun dan mengadakan sinode yang mengutuk simoni (jual-beli jabatan gerejawi).","kisah":"Ia mendukung reformasi biara Cluny dan memperkuat hubungan dengan Kaisar Otto II.","foto":null},{"no":136,"nama":"Paus Yohanes XIV","masa":"983–984","lahir":"Pavia","bio":"Paus keempat yang tidak memakai nama pribadinya (Pietro Canepanova) sebagai nama takhta.","kisah":"Ia dipenjarakan oleh Antipaus Bonifasius VII dan wafat di Kastil Sant'Angelo pada 984.","foto":null},{"no":137,"nama":"Paus Yohanes XV","masa":"985–996","lahir":"Roma","bio":"Paus pertama yang secara resmi mengkanonisasi seorang santo, St. Ulrich dari Augsburg, pada 993.","kisah":"Kanonisasi St. Ulrich (993) menjadi kanonisasi pertama yang tercatat resmi oleh seorang Paus.","foto":null},{"no":138,"nama":"Paus Gregorius V","masa":"996–999","lahir":"±972, Stainach, Kadipaten Kärnten","bio":"Paus resmi pertama dari Jerman, keponakan Kaisar Otto III, yang memahkotainya sebagai kaisar.","kisah":"Ia memahkotai Otto III sebagai Kaisar Romawi Suci pada 996, saat usianya baru sekitar 24 tahun.","foto":null},{"no":139,"nama":"Paus Silvester II","masa":"999–1003","lahir":"±945, Belliac, Kerajaan Franka Barat","bio":"Paus pertama dari Prancis, ilmuwan besar bernama Gerbert dari Aurillac yang memperkenalkan angka Arab ke Eropa.","kisah":"Sebagai cendekiawan, ia dikenal karena keahliannya dalam matematika, astronomi, dan pembuatan jam.","foto":null},{"no":140,"nama":"Paus Yohanes XVII","masa":"1003","lahir":"±955, Roma","bio":"Paus yang memerintah singkat pada 1003, kurang dari enam bulan.","kisah":"Ia dipilih atas pengaruh keluarga Crescentii yang berkuasa di Roma saat itu.","foto":null},{"no":141,"nama":"Paus Yohanes XVIII","masa":"1003–1009","lahir":"±965, Rapagnano","bio":"Paus yang memerintah pada awal abad ke-11 dan berusaha mendamaikan Gereja Roma dengan Konstantinopel.","kisah":"Ia mengutus utusan ke Konstantinopel untuk memperbaiki hubungan setelah ketegangan panjang.","foto":null},{"no":142,"nama":"Paus Sergius IV","masa":"1009–1012","lahir":"±970, Roma","bio":"Paus Benediktin yang memerintah pada 1009–1012.","kisah":"Masa jabatannya berlangsung saat Gereja Makam Kudus di Yerusalem dihancurkan oleh Khalifah Al-Hakim pada 1009.","foto":null},{"no":143,"nama":"Paus Benediktus VIII","masa":"1012–1024","lahir":"±980, Roma","bio":"Paus yang memperkuat kepausan dengan bantuan Kaisar Heinrich II dan mengalahkan Saracen di Sardinia.","kisah":"Ia memahkotai Heinrich II sebagai Kaisar Romawi Suci pada 1014 dan memperkenalkan Credo dalam Misa Minggu di Roma.","foto":null},{"no":144,"nama":"Paus Yohanes XIX","masa":"1024–1032","lahir":"±975, Roma","bio":"Adik Benediktus VIII yang menjadi Paus meskipun sebelumnya seorang awam.","kisah":"Ia ditahbiskan menjadi imam dan uskup dalam waktu singkat sebelum naik takhta kepausan.","foto":null},{"no":145,"nama":"Paus Benediktus IX","masa":"1032–1044","lahir":"±1012, Roma","bio":"Paus termuda dalam sejarah, naik takhta sekitar usia 20 tahun pada 1032; masa jabatan pertamanya berakhir saat ia mengundurkan diri pada 1044.","kisah":"Ia menjadi Paus pada usia sekitar 20 tahun, yang termuda dalam sejarah Gereja.","foto":null},{"no":146,"nama":"Paus Silvester III","masa":"1045","lahir":"±1000, Roma","bio":"Paus yang memerintah hanya 56 hari pada 1045; keabsahan pemilihannya diperdebatkan dan ia dicopot di Konsili Sutri.","kisah":"Ia naik takhta setelah Benediktus IX mengundurkan diri, lalu dicopot oleh Kaisar Heinrich III di Konsili Sutri.","foto":null},{"no":147,"nama":"Paus Benediktus IX","masa":"1045","lahir":"±1012, Roma","bio":"Kembali merebut takhta kepausan pada Maret 1045 setelah menjualnya kepada Gregorius VI, lalu memerintah hanya 52 hari.","kisah":"Ia dicopot di Konsili Sutri pada Desember 1046.","foto":null},{"no":148,"nama":"Paus Gregorius VI","masa":"1045–1046","lahir":"±1000, Roma","bio":"Paus yang membeli jabatan dari Benediktus IX, lalu dicopot di Konsili Sutri karena simoni.","kisah":"Meski dicopot karena membeli jabatan, ia dikenang sebagai Paus yang saleh dan didampingi Hildebrand, kelak Gregorius VII.","foto":null},{"no":149,"nama":"Paus Klemens II","masa":"1046–1047","lahir":"±967, Hornburg, Kadipaten Sachsen","bio":"Paus Jerman yang diangkat oleh Kaisar Heinrich III di Konsili Sutri dan memahkotainya sebagai kaisar pada 1046.","kisah":"Ia memahkotai Heinrich III pada Hari Natal 1046, sehari setelah naik takhta.","foto":null},{"no":150,"nama":"Paus Benediktus IX","masa":"1047–1048","lahir":"±1012, Roma","bio":"Merebut kembali takhta untuk ketiga kalinya pada November 1047 dan memerintah hingga Juli 1048.","kisah":"Ia dicopot dan diekskomunikasi, mengakhiri karier kepausannya yang penuh skandal.","foto":null},{"no":151,"nama":"Paus Damasus II","masa":"1048","lahir":"±1000, Pildenau, Kadipaten Bayern","bio":"Paus Jerman yang memerintah hanya 23 hari pada 1048.","kisah":"Ia wafat di Palestrina setelah tiga minggu memerintah, kemungkinan karena malaria.","foto":null},{"no":152,"nama":"St. Leo IX","masa":"1049–1054","lahir":"21 Juli 1002, Eguisheim, Kadipaten Swabia","bio":"Paus santo yang memimpin reformasi Gereja dan mengadakan sinode-sinode melawan simoni; pada masanya terjadi Skisma Timur-Barat (1054).","kisah":"Utusannya, Kardinal Humbertus, mengucilkan Patriark Konstantinopel pada 1054, memicu perpecahan Gereja Timur dan Barat.","foto":null},{"no":153,"nama":"Paus Viktor II","masa":"1055–1057","lahir":"±1018, Kadipaten Swabia","bio":"Paus Jerman yang melanjutkan reformasi Leo IX dan menjadi wali Kaisar Heinrich IV yang masih kecil.","kisah":"Setelah wafatnya Kaisar Heinrich III, ia menjadi pelindung kaisar muda Heinrich IV.","foto":null},{"no":154,"nama":"Paus Stefanus IX","masa":"1057–1058","lahir":"±1020, Kadipaten Lorraine","bio":"Paus Benediktin dari Lorraine, Paus Jerman terakhir hingga Benediktus XVI (2005).","kisah":"Ia mengangkat Hildebrand (kelak Gregorius VII) sebagai penasihat utamanya dalam reformasi Gereja.","foto":null},{"no":155,"nama":"Paus Nikolaus II","masa":"1058–1061","lahir":"±980, Kastel Chevron, County Savoy","bio":"Paus yang menetapkan Dewan Kardinal sebagai satu-satunya pemilih Paus melalui bulla 'In nomine Domini' (1059).","kisah":"Bulla 'In nomine Domini' mengakhiri campur tangan kaisar dan bangsawan dalam pemilihan Paus.","foto":null},{"no":156,"nama":"Paus Aleksander II","masa":"1061–1073","lahir":"±1018, Baggio, Milan","bio":"Paus yang merestui penaklukan Inggris oleh bangsa Norman di bawah William sang Penakluk (1066).","kisah":"Ia memberkati panji William sang Penakluk sebelum Pertempuran Hastings, yang mengubah sejarah Inggris.","foto":null},{"no":157,"nama":"St. Gregorius VII","masa":"1073–1085","lahir":"±1015, Sovana, Toscana","bio":"Paus santo pelopor Reformasi Gregorian yang memperjuangkan kebebasan Gereja dari kekuasaan raja dan melawan investitur awam.","kisah":"Kaisar Heinrich IV berlutut memohon ampun kepadanya di Canossa pada 1077 setelah dikucilkan.","foto":null},{"no":158,"nama":"Paus Viktor III","masa":"1086–1087","lahir":"±1026, Benevento","bio":"Paus Benediktin dan Abbas Montecassino yang mengadakan Sinode Benevento (1087) mengutuk investitur awam.","kisah":"Ia terpilih setelah penolakan panjang, karena merasa tidak layak menggantikan Gregorius VII.","foto":null},{"no":159,"nama":"Paus Urbanus II","masa":"1088–1099","lahir":"±1042, Châtillon-sur-Marne, Champagne, Kerajaan Prancis","bio":"Paus yang menyerukan Perang Salib Pertama di Konsili Clermont (1095) untuk merebut kembali Tanah Suci.","kisah":"Seruannya di Clermont menggerakkan puluhan ribu orang Eropa menuju Yerusalem, yang direbut pada 1099.","foto":null},{"no":160,"nama":"Paus Paskalis II","masa":"1099–1118","lahir":"±1050, Bleda, Toscana","bio":"Paus Benediktin yang melanjutkan perjuangan melawan investitur awam dan memerintahkan pembangunan Basilika Santi Quattro Coronati.","kisah":"Ia ditangkap Kaisar Heinrich V pada 1111 dan dipaksa menandatangani perjanjian yang kemudian dibatalkannya.","foto":null},{"no":161,"nama":"Paus Gelasius II","masa":"1118–1119","lahir":"±1061, Gaeta","bio":"Paus Benediktin yang memerintah singkat di tengah konflik dengan Kaisar Heinrich V dan Antipaus Gregorius VIII.","kisah":"Ia wafat dalam pengasingan di Biara Cluny, Prancis, setelah melarikan diri dari Roma.","foto":null},{"no":162,"nama":"Paus Kalistus II","masa":"1119–1124","lahir":"±1060, Quingey, County Bourgogne","bio":"Paus yang mengadakan Konsili Lateran I (1123) dan menandatangani Konkordat Worms (1122) yang mengakhiri Kontroversi Investitur.","kisah":"Konkordat Worms membagi kewenangan pengangkatan uskup antara Paus dan kaisar, mengakhiri konflik puluhan tahun.","foto":null},{"no":163,"nama":"Paus Honorius II","masa":"1124–1130","lahir":"9 Februari 1060, Fiagnano","bio":"Paus yang menyetujui Ordo Ksatria Templar sebagai ordo militer pada 1128.","kisah":"Persetujuannya atas Templar membuka jalan bagi ordo militer pertama yang melindungi peziarah di Tanah Suci.","foto":null},{"no":164,"nama":"Paus Inosensius II","masa":"1130–1143","lahir":"±1082, Roma","bio":"Paus yang mengadakan Konsili Lateran II (1139) setelah mengalahkan Antipaus Anakletus II.","kisah":"Ia memulihkan kesatuan Gereja setelah skisma delapan tahun melawan Antipaus Anakletus II.","foto":null},{"no":165,"nama":"Paus Selestinus II","masa":"1143–1144","lahir":"±1085, Città di Castello","bio":"Paus yang memerintah singkat pada 1143–1144.","kisah":"Ia mengangkat kembali St. Bernard dari Clairvaux sebagai penasihat dan menghapus beberapa hukuman pendahulunya.","foto":null},{"no":166,"nama":"Paus Lusius II","masa":"1144–1145","lahir":"±1079, Bologna","bio":"Paus yang wafat karena luka saat memimpin serangan terhadap Senat Roma yang memberontak pada 1145.","kisah":"Ia memimpin sendiri pasukan untuk merebut kembali Roma dari kaum republikan dan tewas terkena lemparan batu.","foto":null},{"no":167,"nama":"Paus Eugenius III","masa":"1145–1153","lahir":"±1080, Pisa","bio":"Paus Sistersian pertama, murid St. Bernard dari Clairvaux, yang menyerukan Perang Salib Kedua (1147).","kisah":"Perang Salib Kedua yang diserukannya berakhir gagal di Damaskus, tetapi ia tetap dihormati sebagai Beato.","foto":null},{"no":168,"nama":"Paus Anastasius IV","masa":"1153–1154","lahir":"±1073, Roma","bio":"Paus yang memerintah singkat pada 1153–1154 dan dikenal sebagai pendamai.","kisah":"Ia berdamai dengan Kaisar Friedrich I Barbarossa dan mengakhiri konflik dengan Roma.","foto":null},{"no":169,"nama":"Paus Adrianus IV","masa":"1154–1159","lahir":"±1100, Abbots Langley, Hertfordshire, Kerajaan Inggris","bio":"Satu-satunya Paus dari Inggris, Nicholas Breakspear, yang konon memberikan Irlandia kepada Raja Henry II.","kisah":"Dari anak yatim yang ditolak masuk biara, ia menjadi satu-satunya Paus Inggris dalam sejarah.","foto":null},{"no":170,"nama":"Paus Aleksander III","masa":"1159–1181","lahir":"±1100, Siena, Toscana","bio":"Paus yang memerintah 22 tahun, mengadakan Konsili Lateran III (1179), dan mendukung Thomas Becket melawan Henry II.","kisah":"Ia mengkanonisasi St. Thomas Becket pada 1173, tiga tahun setelah pembunuhannya di Katedral Canterbury.","foto":null},{"no":171,"nama":"Paus Lusius III","masa":"1181–1185","lahir":"±1100, Lucca, Toscana","bio":"Paus yang mengeluarkan bulla 'Ad abolendam' (1184) melawan bidaah, cikal bakal Inkuisisi.","kisah":"Ia mengadakan Konsili Verona (1184) bersama Kaisar Friedrich Barbarossa untuk menindak kaum Katar.","foto":null},{"no":172,"nama":"Paus Urbanus III","masa":"1185–1187","lahir":"±1120, Cuggiono, dekat Milan","bio":"Paus yang memerintah saat Yerusalem jatuh ke tangan Salahuddin al-Ayyubi pada 1187.","kisah":"Berita jatuhnya Yerusalem pada Oktober 1187 disebut-sebut mempercepat kematiannya karena duka.","foto":null},{"no":173,"nama":"Paus Gregorius VIII","masa":"1187","lahir":"±1100, Benevento","bio":"Paus yang memerintah hanya 57 hari dan menyerukan Perang Salib Ketiga setelah jatuhnya Yerusalem.","kisah":"Dalam masa jabatannya yang singkat, ia menyerukan Perang Salib Ketiga yang kemudian dipimpin tiga raja Eropa.","foto":null},{"no":174,"nama":"Paus Klemens III","masa":"1187–1191","lahir":"±1130, Roma","bio":"Paus yang berdamai dengan Kaisar Friedrich Barbarossa dan mendukung Perang Salib Ketiga.","kisah":"Ia kembali ke Roma pada 1188 setelah bertahun-tahun kepausan berada di luar kota akibat konflik dengan kekaisaran.","foto":null},{"no":175,"nama":"Paus Selestinus III","masa":"1191–1198","lahir":"±1105, Roma","bio":"Paus yang mengesahkan statuta Ksatria Teutonik sebagai ordo militer dan memahkotai Kaisar Heinrich VI.","kisah":"Ia memahkotai Heinrich VI pada 1191, tetapi hubungan keduanya memburuk karena penahanan Richard I dari Inggris.","foto":null},{"no":176,"nama":"Paus Inosensius III","masa":"1198–1216","lahir":"±1161, Gavignano","bio":"Salah satu Paus paling berkuasa dalam sejarah; ia mengadakan Konsili Lateran IV (1215) dan merestui Ordo Fransiskan.","kisah":"Ia menyerukan Perang Salib Keempat, tetapi menjauhinya setelah pasukan salib menjarah Konstantinopel yang Kristen.","foto":null},{"no":177,"nama":"Paus Honorius III","masa":"1216–1227","lahir":"±1150, Roma","bio":"Paus yang menyerukan Perang Salib Kelima dan menyetujui beberapa ordo religius, termasuk Ordo Dominikan.","kisah":"Ia menyetujui Ordo Pengkhotbah (Dominikan) pada 1216 dan Regula St. Fransiskus pada 1223.","foto":null},{"no":178,"nama":"Paus Gregorius IX","masa":"1227–1241","lahir":"±1145, Anagni","bio":"Paus yang mengkanonisasi St. Fransiskus dari Asisi (1228) dan mengawali Inkuisisi di Prancis.","kisah":"Ia mengkanonisasi St. Fransiskus hanya dua tahun setelah wafatnya, dan St. Dominikus pada 1234.","foto":null},{"no":179,"nama":"Paus Selestinus IV","masa":"1241","lahir":"±1180, Milan","bio":"Paus yang memerintah hanya 16 hari pada 1241 dan wafat sebelum sempat dimahkotai.","kisah":"Ia terpilih setelah konklaf yang tegang di tengah pengepungan Roma oleh Kaisar Friedrich II.","foto":null},{"no":180,"nama":"Paus Inosensius IV","masa":"1243–1254","lahir":"±1195, Genoa","bio":"Paus ahli hukum kanon yang mengadakan Konsili Lyon I (1245) dan mengucilkan Kaisar Friedrich II.","kisah":"Ia melarikan diri ke Lyon, Prancis, untuk mengadakan konsili yang memecat Friedrich II dari takhta kekaisaran.","foto":null},{"no":181,"nama":"Paus Aleksander IV","masa":"1254–1261","lahir":"±1185–1199, Jenne, Italia","bio":"Paus dari keluarga Conti di Segni, keponakan Gregorius IX; ia memulihkan Inkuisisi kepausan di Prancis dan berjuang mempertahankan Negara Gereja melawan kaum Hohenstaufen.","kisah":"Ia mengorganisasi perang salib melawan Manfred dari Sisilia demi merebut kembali Kerajaan Sisilia.","foto":null},{"no":182,"nama":"Paus Urbanus IV","masa":"1261–1264","lahir":"±1195, Troyes, Prancis","bio":"Putra seorang pembuat sepatu dari Troyes yang pernah menjadi Patriark Yerusalem; ia menetapkan perayaan Corpus Christi pada 1264.","kisah":"Atas permintaannya, St. Tomas Aquinas menyusun liturgi dan himne untuk perayaan Corpus Christi.","foto":null},{"no":183,"nama":"Paus Klemens IV","masa":"1265–1268","lahir":"23 November 1190, Saint-Gilles, Prancis","bio":"Seorang ahli hukum dan mantan tentara yang mendukung Charles dari Anjou merebut Sisilia dari kaum Hohenstaufen.","kisah":"Ia mengangkat Charles dari Anjou sebagai Raja Sisilia, mengubah peta politik Italia.","foto":null},{"no":184,"nama":"Paus Gregorius X","masa":"1271–1276","lahir":"±1210, Piacenza, Italia","bio":"Beato Gregorius X memimpin Konsili Lyon II (1274) dan menerbitkan bulla Ubi periculum yang mengatur tata cara konklaf hingga abad ke-20.","kisah":"Ia terpilih setelah kekosongan Takhta Suci terpanjang dalam sejarah Gereja, hampir tiga tahun.","foto":null},{"no":185,"nama":"Paus Inosensius V","masa":"1276","lahir":"±1225, Savoia","bio":"Paus pertama dari Ordo Dominikan dan Paus pertama yang dipilih dalam konklaf; masa kepausannya hanya berlangsung lima bulan.","kisah":"Sebagai teolog, ia menulis komentar atas Surat-surat St. Paulus dan Kitab Suci.","foto":null},{"no":186,"nama":"Paus Adrianus V","masa":"1276","lahir":"±1216, Genoa, Italia","bio":"Keponakan Paus Inosensius IV yang hanya memerintah 38 hari; ia membatalkan aturan konklaf ketat yang dibuat Gregorius X.","kisah":"Ia wafat di Viterbo sebelum sempat dimahkotai sebagai Paus.","foto":null},{"no":187,"nama":"Paus Yohanes XXI","masa":"1276–1277","lahir":"±1215, Lisboa, Portugal","bio":"Satu-satunya Paus asal Portugal, seorang dokter dan filsuf terkenal yang menulis risalah logika dan kedokteran.","kisah":"Ia wafat setelah langit-langit kamar barunya di Istana Kepausan Viterbo runtuh menimpanya.","foto":null},{"no":188,"nama":"Paus Nikolaus III","masa":"1277–1280","lahir":"±1216, Roma, Italia","bio":"Paus dari keluarga Orsini yang memperkuat kekuasaan kepausan di Italia dan mengusahakan persatuan dengan Gereja Timur.","kisah":"Ia dikenal karena nepotisme besar-besaran, mengangkat banyak kerabatnya menjadi kardinal dan penguasa wilayah.","foto":null},{"no":189,"nama":"Paus Martinus IV","masa":"1281–1285","lahir":"±1210, Meinpicien, Prancis","bio":"Paus Prancis yang memerintah dari Orvieto; masa kepausannya diwarnai Pemberontakan Vesper Sisilia dan Perang Salib Aragon.","kisah":"Ia mengkanonisasi Raja Louis IX dari Prancis, satu-satunya raja Prancis yang menjadi santo.","foto":null},{"no":190,"nama":"Paus Honorius IV","masa":"1285–1287","lahir":"±1210, Roma, Italia","bio":"Paus yang lumpuh karena encok dan hanya memerintah dua tahun; ia melanjutkan kebijakan keras pendahulunya terhadap Aragon dan Sisilia.","kisah":"Meski lumpuh, ia memimpin Gereja dengan tegas dan mengutuk para pemberontak Sisilia.","foto":null},{"no":191,"nama":"Paus Nikolaus IV","masa":"1288–1292","lahir":"30 September 1227, Lisciano, Italia","bio":"Paus Fransiskan pertama, seorang misionaris yang mengirim utusan ke istana Mongol dan memperkuat misi Gereja ke Asia.","kisah":"Ia mengutus Fransiskan Yohanes dari Montecorvino ke Tiongkok, yang kemudian menjadi Uskup Agung pertama Beijing.","foto":null},{"no":192,"nama":"St. Selestinus V","masa":"1294","lahir":"±1215, Sant'Angelo Limosano, Italia","bio":"Seorang pertapa suci pendiri Ordo Selestin yang terpilih menjadi Paus pada usia 79 tahun dan mengundurkan diri setelah lima bulan.","kisah":"Pengunduran dirinya yang rendah hati mengilhami Dante, dan ia dikanonisasi pada 1313.","foto":null},{"no":193,"nama":"Paus Bonifasius VIII","masa":"1294–1303","lahir":"±1235, Anagni, Italia","bio":"Paus yang mengeluarkan bulla Unam Sanctam (1302) tentang supremasi kepausan dan meresmikan Tahun Yubileum pertama pada 1300.","kisah":"Konfliknya dengan Raja Philip IV dari Prancis berakhir dengan penangkapannya di Anagni, dan ia wafat tak lama kemudian.","foto":null},{"no":194,"nama":"Paus Benediktus XI","masa":"1303–1304","lahir":"±1240, Treviso, Italia","bio":"Beato Benediktus XI, seorang Dominikan yang berusaha mendamaikan Gereja dengan Prancis setelah masa Bonifasius VIII.","kisah":"Ia membatalkan bulla Unam Sanctam dan wafat mendadak di Perugia setelah delapan bulan memerintah.","foto":null},{"no":195,"nama":"Paus Klemens V","masa":"1305–1314","lahir":"±1264, Villandraut, Prancis","bio":"Paus Prancis pertama dari masa Avignon; ia memindahkan Takhta Suci ke Avignon pada 1309 dan membubarkan Ordo Kesatria Templar.","kisah":"Di bawah tekanan Raja Philip IV, ia mengeluarkan bulla yang memulai penganiayaan terhadap para Kesatria Templar.","foto":null},{"no":196,"nama":"Paus Yohanes XXII","masa":"1316–1334","lahir":"±1244, Cahors, Prancis","bio":"Paus Avignon yang memerintah 18 tahun; ia berselisih dengan Ordo Fransiskan soal kemiskinan Kristus dan dengan Kaisar Ludwig dari Bavaria.","kisah":"Pandangan kontroversialnya tentang visiun beatifika sempat menimbulkan kegemparan teologi di seluruh Eropa.","foto":null},{"no":197,"nama":"Paus Benediktus XII","masa":"1334–1342","lahir":"1285, Saverdun, Prancis","bio":"Seorang rahib Sistersian yang hidup sederhana; ia menerbitkan konstitusi Benedictus Deus (1336) tentang visiun beatifika dan mereformasi ordo-ordo religius.","kisah":"Ia menolak kembali ke Roma dan malah membangun Istana Kepausan yang megah di Avignon.","foto":null},{"no":198,"nama":"Paus Klemens VI","masa":"1342–1352","lahir":"±1291, Maumont, Prancis","bio":"Paus Avignon yang memerintah pada masa Wabah Hitam; ia membeli kota Avignon dari Ratu Joanna dari Napoli dan melindungi orang Yahudi dari penganiayaan.","kisah":"Selama wabah, ia mengampuni dosa semua yang meninggal karena penyakit pes dan mengadakan misa bagi para korban.","foto":null},{"no":199,"nama":"Paus Inosensius VI","masa":"1352–1362","lahir":"±1282, Les Monts, Prancis","bio":"Paus Avignon yang hemat dan sederhana; melalui usahanya, Perjanjian Brétigny (1360) antara Inggris dan Prancis ditandatangani.","kisah":"Ia mengirim Kardinal Albornoz untuk merebut kembali Negara Gereja di Italia dari para penguasa lokal.","foto":null},{"no":200,"nama":"Paus Urbanus V","masa":"1362–1370","lahir":"1310, Grizac, Prancis","bio":"Beato Urbanus V, seorang Benediktin yang sempat mengembalikan Takhta Suci ke Roma pada 1367 sebelum kembali ke Avignon.","kisah":"Ia mereformasi pendidikan, mendirikan banyak universitas, dan mengirim misionaris ke Eropa dan Asia.","foto":null},{"no":201,"nama":"Paus Gregorius XI","masa":"1370–1378","lahir":"±1329, Maumont, Prancis","bio":"Paus Prancis terakhir; ia secara permanen mengembalikan Takhta Suci dari Avignon ke Roma pada 1377.","kisah":"Keputusannya kembali ke Roma dipengaruhi desakan St. Katarina dari Siena yang menulis surat-surat memohon kepadanya.","foto":null},{"no":202,"nama":"Paus Urbanus VI","masa":"1378–1389","lahir":"±1318, Napoli, Italia","bio":"Paus Italia pertama setelah masa Avignon; pemilihannya memicu Skisma Barat karena para kardinal Prancis memilih Paus tandingan di Avignon.","kisah":"Ia adalah Paus terakhir yang dipilih dari luar Dewan Kardinal.","foto":null},{"no":203,"nama":"Paus Bonifasius IX","masa":"1389–1404","lahir":"±1350, Napoli, Italia","bio":"Paus Roma pada masa Skisma Barat; ia memperkuat posisi Roma dengan mengangkat banyak kardinal baru dan merayakan Tahun Yubileum 1400.","kisah":"Ia menolak mengundurkan diri demi persatuan Gereja, sehingga skisma berlanjut setelah wafatnya.","foto":null},{"no":204,"nama":"Paus Inosensius VII","masa":"1404–1406","lahir":"1339, Sulmona, Italia","bio":"Paus Roma pada masa Skisma Barat yang berjanji mengundurkan diri demi persatuan Gereja, tetapi gagal mencapai kesepakatan dengan Paus tandingan Avignon.","kisah":"Keponakannya yang diangkat menjadi kardinal membunuh para pemimpin Roma, memaksanya melarikan diri dari kota.","foto":null},{"no":205,"nama":"Paus Gregorius XII","masa":"1406–1415","lahir":"±1326, Venesia, Italia","bio":"Paus Roma yang mengundurkan diri pada 1415 demi mengakhiri Skisma Barat, atas desakan Konsili Konstanz.","kisah":"Ia adalah Paus terakhir yang mengundurkan diri sebelum Benediktus XVI pada 2013.","foto":null},{"no":206,"nama":"Paus Martinus V","masa":"1417–1431","lahir":"Januari–Februari 1368 atau 1369, Genazzano, Italia","bio":"Paus yang pemilihannya di Konsili Konstanz (1417) secara efektif mengakhiri Skisma Barat; ia memulihkan kekuasaan kepausan di Roma.","kisah":"Ia memanggil Konsili Basel dan memulai pembangunan kembali Roma yang porak-poranda akibat skisma.","foto":null},{"no":207,"nama":"Paus Eugenius IV","masa":"1431–1447","lahir":"1383, Venesia, Italia","bio":"Paus yang memindahkan Konsili Basel ke Ferrara lalu Firenze (1439), tempat persatuan singkat dengan Gereja Ortodoks Timur diproklamasikan.","kisah":"Ia menobatkan Kaisar Sigismund di Roma dan mengeluarkan bulla yang mengutuk perbudakan penduduk asli Kepulauan Kanari.","foto":null},{"no":208,"nama":"Paus Nikolaus V","masa":"1447–1455","lahir":"15 November 1397, Sarzana, Italia","bio":"Paus Renaisans pertama yang mendirikan Perpustakaan Vatikan dan membangun kembali Roma sebagai pusat seni dan ilmu pengetahuan.","kisah":"Pada masa kepausannya, Konstantinopel jatuh ke tangan Ottoman (1453), dan ia menyerukan perang salib baru.","foto":null},{"no":209,"nama":"Paus Kalistus III","masa":"1455–1458","lahir":"31 Desember 1378, Xàtiva, Spanyol","bio":"Paus pertama dari Valencia, Spanyol, dan paman dari Paus Aleksander VI; ia memerintahkan pengadilan ulang Jeanne d'Arc yang berujung pada rehabilitasinya.","kisah":"Ia menetapkan Pesta Transfigurasi setiap 6 Agustus untuk memperingati kemenangan atas Ottoman di Beograd.","foto":null},{"no":210,"nama":"Paus Pius II","masa":"1458–1464","lahir":"18 Oktober 1405, Corsignano, Italia","bio":"Seorang humanis dan penulis terkenal yang sebelum menjadi Paus menulis novel dan sejarah; ia mendirikan kota ideal Pienza.","kisah":"Ia menulis Commentaries, satu-satunya otobiografi yang pernah ditulis seorang Paus.","foto":null},{"no":211,"nama":"Paus Paulus II","masa":"1464–1471","lahir":"23 Februari 1417, Venesia, Italia","bio":"Paus dari Venesia yang membangun Palazzo Venezia dan menyetujui masuknya percetakan ke Negara Gereja.","kisah":"Ia gemar mengumpulkan permata dan barang antik, serta membubarkan Akademi Roma yang dicurigai menyebarkan paham pagan.","foto":null},{"no":212,"nama":"Paus Sistus IV","masa":"1471–1484","lahir":"21 Juli 1414, Celle Ligure, Italia","bio":"Seorang Fransiskan yang membangun Kapel Sistina dan Arsip Vatikan; ia mengizinkan Inkuisisi Spanyol atas permintaan Raja Katolik Spanyol.","kisah":"Ia adalah pelindung seni besar yang membawa para seniman Renaisans awal ke Roma.","foto":null},{"no":213,"nama":"Paus Inosensius VIII","masa":"1484–1492","lahir":"1432, Genoa, Italia","bio":"Paus yang mengangkat Tomás de Torquemada sebagai inkuisitor jenderal Spanyol dan mendukung penuntutan ilmu sihir melalui bulla Summis desiderantes affectibus (1484).","kisah":"Ia adalah Paus pertama yang secara terbuka mengakui anak-anaknya.","foto":null},{"no":214,"nama":"Paus Aleksander VI","masa":"1492–1503","lahir":"1 Januari 1431, Xàtiva, Spanyol","bio":"Rodrigo Borgia, Paus Renaisans paling kontroversial; ia membagi dunia baru antara Spanyol dan Portugal melalui bulla Inter caetera (1493).","kisah":"Nama keluarganya, Borgia, menjadi sinonim nepotisme dan skandal karena anak-anaknya, Cesare dan Lucrezia.","foto":null},{"no":215,"nama":"Paus Pius III","masa":"1503","lahir":"29 Mei 1439, Siena, Italia","bio":"Keponakan Pius II yang hanya memerintah 26 hari; ia mendirikan Perpustakaan Piccolomini di Katedral Siena.","kisah":"Ia wafat karena infeksi pada kakinya hanya sebulan setelah terpilih.","foto":null},{"no":216,"nama":"Paus Yulius II","masa":"1503–1513","lahir":"5 Desember 1443, Albisola, Italia","bio":"Paus Prajurit yang merebut kembali seluruh Negara Gereja dan memulai pembangunan kembali Basilika Santo Petrus; ia menugaskan Michelangelo melukis langit-langit Kapel Sistina.","kisah":"Ia memimpin sendiri pasukannya dalam pertempuran dan mendirikan Garda Swiss pada 1506.","foto":null},{"no":217,"nama":"Paus Leo X","masa":"1513–1521","lahir":"11 Desember 1475, Firenze, Italia","bio":"Putra Lorenzo de' Medici yang menjadi pelindung seni besar; pada masa kepausannya, Martin Luther memakukan 95 Tesis (1517) dan diekskomunikasi (1521).","kisah":"Ia adalah Paus terakhir yang belum menjadi imam saat terpilih, dan ia menutup Konsili Lateran V.","foto":null},{"no":218,"nama":"Paus Adrianus VI","masa":"1522–1523","lahir":"2 Maret 1459, Utrecht, Belanda","bio":"Satu-satunya Paus asal Belanda dan Paus non-Italia terakhir hingga Yohanes Paulus II; ia berusaha mereformasi Kuria menanggapi Reformasi Protestan.","kisah":"Ia secara terbuka mengakui bahwa kekacauan Gereja adalah kesalahan Kuria Roma sendiri.","foto":null},{"no":219,"nama":"Paus Klemens VII","masa":"1523–1534","lahir":"26 Mei 1478, Firenze, Italia","bio":"Sepupu Leo X yang menghadapi Penjarahan Roma (1527) oleh pasukan Kaisar dan menolak perceraian Raja Henry VIII dari Inggris.","kisah":"Penolakannya atas perceraian Henry VIII memicu perpisahan Gereja Inggris dari Roma.","foto":null},{"no":220,"nama":"Paus Paulus III","masa":"1534–1549","lahir":"29 Februari 1468, Canino, Italia","bio":"Paus yang membuka Konsili Trente (1545) dan mengakui Serikat Yesus (1540); ia menunjuk Michelangelo mengawasi pembangunan Basilika Santo Petrus.","kisah":"Ia lahir pada 29 Februari, menjadikannya Paus yang lahir pada hari kabisat.","foto":null},{"no":221,"nama":"Paus Yulius III","masa":"1550–1555","lahir":"10 September 1487, Roma, Italia","bio":"Paus yang membuka kembali Konsili Trente (1551) dan mendirikan Collegium Germanicum untuk pendidikan imam Jerman.","kisah":"Ia dikenal sebagai pecinta musik dan seni, serta pelindung komposer Palestrina.","foto":null},{"no":222,"nama":"Paus Marselus II","masa":"1555","lahir":"6 Mei 1501, Montefano, Italia","bio":"Paus terakhir yang memakai nama lahirnya sebagai nama kepausan; ia hanya memerintah 22 hari dan segera melakukan penghematan di Takhta Suci.","kisah":"Missa Papae Marcelli karya Palestrina digubah untuk menghormatinya.","foto":null},{"no":223,"nama":"Paus Paulus IV","masa":"1555–1559","lahir":"28 Juni 1476, Capriglia Irpina, Italia","bio":"Pendiri Ordo Teatin yang keras; ia mendirikan Ghetto Yahudi Roma (1555) dan menerbitkan Indeks Buku Terlarang (1559).","kisah":"Ia memerintahkan Michelangelo menutup aurat tokoh-tokoh telanjang dalam lukisan Pengadilan Terakhir.","foto":null},{"no":224,"nama":"Paus Pius IV","masa":"1559–1565","lahir":"31 Maret 1499, Milan, Italia","bio":"Paus yang membuka kembali dan menutup Konsili Trente (1563) serta menetapkan Pengakuan Iman Tridentin.","kisah":"Ia memerintahkan pembangunan kembali Roma, termasuk perbaikan pasokan air kota.","foto":null},{"no":225,"nama":"St. Pius V","masa":"1566–1572","lahir":"17 Januari 1504, Bosco Marengo, Italia","bio":"Santo Pius V, seorang Dominikan yang menerapkan keputusan Konsili Trente, menerbitkan Misale Romawi 1570, dan mengorganisasi Liga Suci yang menang di Lepanto (1571).","kisah":"Ia menetapkan Pesta Santa Perawan Maria Ratu Rosario untuk memperingati kemenangan Lepanto.","foto":null},{"no":226,"nama":"Paus Gregorius XIII","masa":"1572–1585","lahir":"7 Januari 1502, Bologna, Italia","bio":"Paus yang mereformasi kalender pada 1582, menghasilkan Kalender Gregorian yang dipakai seluruh dunia hingga kini.","kisah":"Ia mendirikan banyak perguruan Yesuit dan memperkuat hubungan diplomatik dengan negara-negara Asia.","foto":null},{"no":227,"nama":"Paus Sistus V","masa":"1585–1590","lahir":"13 Desember 1521, Grottammare, Italia","bio":"Seorang Fransiskan Konventual yang menata ulang Roma dengan jalan-jalan dan obelisk baru serta membatasi jumlah kardinal menjadi 70.","kisah":"Ia menyelesaikan kubah Basilika Santo Petrus dan membangun gedung baru Perpustakaan Vatikan.","foto":null},{"no":228,"nama":"Paus Urbanus VII","masa":"1590","lahir":"4 Agustus 1521, Roma, Italia","bio":"Paus dengan masa pemerintahan tersingkat, hanya 12 hari; ia menetapkan larangan merokok pertama di dunia di dalam dan sekitar gereja.","kisah":"Ia wafat sebelum sempat dimahkotai, setelah mewariskan seluruh hartanya untuk amal.","foto":null},{"no":229,"nama":"Paus Gregorius XIV","masa":"1590–1591","lahir":"11 Februari 1535, Somma Lombardo, Italia","bio":"Paus yang melarang perjudian atas hasil pemilihan Paus dengan ancaman ekskomunikasi melalui bulla Cogit nos (1591).","kisah":"Ia mengubah aturan pendahulunya tentang hukuman aborsi, membatasinya pada janin yang sudah bernyawa.","foto":null},{"no":230,"nama":"Paus Inosensius IX","masa":"1591","lahir":"20 Juli 1519, Bologna, Italia","bio":"Paus yang hanya memerintah 62 hari; ia mendukung Liga Katolik Prancis melawan Raja Henry IV.","kisah":"Ia melarang penjualan harta Gereja dan wafat setelah dua bulan memerintah.","foto":null},{"no":231,"nama":"Paus Klemens VIII","masa":"1592–1605","lahir":"24 Februari 1536, Fano, Italia","bio":"Paus yang berdamai dengan Raja Henry IV dari Prancis dan memimpin aliansi Kristen melawan Ottoman dalam Perang Panjang.","kisah":"Ia memimpin Kongregasi de Auxiliis yang membahas perdebatan teologi antara Dominikan dan Yesuit tentang rahmat.","foto":null},{"no":232,"nama":"Paus Leo XI","masa":"1605","lahir":"2 Juni 1535, Firenze, Italia","bio":"Paus Medici yang dijuluki 'Paus Kilat' karena hanya memerintah 26 hari.","kisah":"Ia adalah keponakan buyut Paus Leo X dan dikenal karena kesalehan serta kedermawanannya.","foto":null},{"no":233,"nama":"Paus Paulus V","masa":"1605–1621","lahir":"17 September 1550 atau 1552, Roma, Italia","bio":"Paus yang membiayai fasad Basilika Santo Petrus dan mendirikan Bank Roh Kudus; ia berselisih dengan Venesia dan memperingatkan Galileo pada 1616.","kisah":"Ia memulihkan saluran air Aqua Traiana yang memasok air ke Roma.","foto":null},{"no":234,"nama":"Paus Gregorius XV","masa":"1621–1623","lahir":"9 Januari 1554, Bologna, Italia","bio":"Paus yang mendirikan Kongregasi Propaganda Fide (1622) untuk misi dunia dan menetapkan pemilihan Paus melalui pemungutan suara rahasia.","kisah":"Ia mengkanonisasi St. Ignatius dari Loyola, St. Fransiskus Xaverius, dan St. Teresa dari Avila dalam satu upacara.","foto":null},{"no":235,"nama":"Paus Urbanus VIII","masa":"1623–1644","lahir":"5 April 1568, Firenze, Italia","bio":"Paus Barberini yang memerintah 21 tahun; pada masa kepausannya berlangsung pengadilan Galileo Galilei (1633).","kisah":"Ia adalah Paus terakhir yang memperluas wilayah kepausan dengan kekuatan senjata.","foto":null},{"no":236,"nama":"Paus Inosensius X","masa":"1644–1655","lahir":"6 Mei 1574, Roma, Italia","bio":"Paus yang menentang Perdamaian Westphalia dan membangun Air Mancur Empat Sungai di Piazza Navona, Roma.","kisah":"Ia mengutuk lima dalil Jansenisme melalui konstitusi Cum occasione (1653).","foto":null},{"no":237,"nama":"Paus Aleksander VII","masa":"1655–1667","lahir":"13 Februari 1599, Siena, Italia","bio":"Paus yang menugaskan Bernini membangun Kolonade Lapangan Santo Petrus dan menetapkan doktrin Dikandung Tanpa Noda (1661).","kisah":"Ia adalah keponakan buyut Paus Paulus V dan pelindung besar seni Barok Roma.","foto":null},{"no":238,"nama":"Paus Klemens IX","masa":"1667–1669","lahir":"28 Januari 1600, Pistoia, Italia","bio":"Paus yang menengahi Perdamaian Aachen (1668) antara Prancis dan Spanyol; ia dikenal karena kesederhanaan dan kerendahan hatinya.","kisah":"Ia menolak memperkaya keluarganya dan dikenal murah hati kepada fakir miskin.","foto":null},{"no":239,"nama":"Paus Klemens X","masa":"1670–1676","lahir":"13 Juli 1590, Roma, Italia","bio":"Paus yang mengkanonisasi St. Rosa dari Lima (1671), santa pertama dari benua Amerika.","kisah":"Ia terpilih pada usia 79 tahun dan menghiasi Jembatan Sant'Angelo dengan sepuluh patung malaikat.","foto":null},{"no":240,"nama":"Paus Inosensius XI","masa":"1676–1689","lahir":"16 Mei 1611, Como, Italia","bio":"Beato Inosensius XI yang mengorganisasi Liga Suci yang membebaskan Wina dari Ottoman (1683) dan menetapkan Pesta Nama Santa Perawan Maria.","kisah":"Ia dikagumi karena kesalehan dan ketegasannya melawan nepotisme di Kuria Roma.","foto":null},{"no":241,"nama":"Paus Aleksander VIII","masa":"1689–1691","lahir":"22 April 1610, Venesia, Italia","bio":"Paus Venesia yang mengutuk apa yang disebut 'dosa filosofis' dan memperkaya Perpustakaan Vatikan dengan banyak manuskrip kuno.","kisah":"Ia membeli koleksi perpustakaan Ratu Kristina dari Swedia untuk Perpustakaan Vatikan.","foto":null},{"no":242,"nama":"Paus Inosensius XII","masa":"1691–1700","lahir":"13 Maret 1615, Spinazzola, Italia","bio":"Paus yang menghapus nepotisme melalui bulla Romanum decet Pontificem (1692) dan mendirikan banyak lembaga amal dan pendidikan.","kisah":"Ia melarang para Paus memberikan jabatan dan kekayaan kepada kerabat mereka.","foto":null},{"no":243,"nama":"Paus Klemens XI","masa":"1700–1721","lahir":"23 Juli 1649, Urbino, Italia","bio":"Paus yang menghadapi Kontroversi Ritus Tiongkok dan menjadikan Pesta Dikandung Tanpa Noda sebagai perayaan universal.","kisah":"Ia melindungi penggalian arkeologi pertama di katakombe Roma dan mencabut sebagian larangan atas karya Galileo.","foto":null},{"no":244,"nama":"Paus Inosensius XIII","masa":"1721–1724","lahir":"13 Mei 1655, Poli, Italia","bio":"Paus yang melarang Yesuit menerima anggota baru di Tiongkok dan menerbitkan bulla Apostolici Ministerii (1724) tentang disiplin gerejawi di Spanyol.","kisah":"Ia berasal dari keluarga Conti, keluarga yang telah memberi banyak Paus bagi Gereja.","foto":null},{"no":245,"nama":"Paus Benediktus XIII","masa":"1724–1730","lahir":"2 Februari 1649, Gravina in Puglia, Italia","bio":"Seorang Dominikan yang saleh dan sederhana, Paus terakhir dari keluarga Orsini; ia mencabut larangan merokok sedunia yang ditetapkan pendahulunya.","kisah":"Pada masa kepausannya, James Bradley menemukan aberasi bintang yang membuktikan gerak Bumi mengelilingi Matahari.","foto":null},{"no":246,"nama":"Paus Klemens XII","masa":"1730–1740","lahir":"7 April 1652, Firenze, Italia","bio":"Paus yang memerintahkan pembangunan Air Mancur Trevi (1732) dan mengutuk Freemasonry melalui bulla In eminenti apostolatus (1738).","kisah":"Meski buta pada usia lanjut, ia tetap memimpin Gereja hingga usia 87 tahun.","foto":null},{"no":247,"nama":"Paus Benediktus XIV","masa":"1740–1758","lahir":"31 Maret 1675, Bologna, Italia","bio":"Paus cendekiawan yang mereformasi pendidikan imam, menyelesaikan Air Mancur Trevi, dan mengizinkan penerbitan karya ilmiah Galileo.","kisah":"Ia mendirikan akademi seni, liturgi, dan ilmu pengetahuan, serta menegaskan ajaran St. Tomas Aquinas.","foto":null},{"no":248,"nama":"Paus Klemens XIII","masa":"1758–1769","lahir":"7 Maret 1693, Venesia, Italia","bio":"Paus yang membela Serikat Yesus melalui bulla Apostolicum pascendi (1765) di tengah tekanan raja-raja Eropa untuk membubarkannya.","kisah":"Ia memerintahkan penambahan daun ara pada patung-patung telanjang di Vatikan.","foto":null},{"no":249,"nama":"Paus Klemens XIV","masa":"1769–1774","lahir":"31 Oktober 1705, Santarcangelo di Romagna, Italia","bio":"Seorang Fransiskan Konventual yang membubarkan Serikat Yesus melalui brief Dominus ac Redemptor (1773) di bawah tekanan para raja Bourbon.","kisah":"Ia wafat setahun setelah membubarkan Yesuit, dan kematiannya sempat memicu rumor bahwa ia diracun.","foto":null},{"no":250,"nama":"Paus Pius VI","masa":"1775–1799","lahir":"25 Desember 1717, Cesena, Italia","bio":"Paus yang mengutuk Revolusi Prancis dan wafat sebagai tawanan Prancis di Valence pada 1799 setelah diusir dari Negara Gereja.","kisah":"Ia adalah Paus terakhir yang menjadi pelindung seni Renaisans dan wafat dalam pengasingan.","foto":null},{"no":251,"nama":"Paus Pius VII","masa":"1800–1823","lahir":"14 Agustus 1742, Cesena, Italia","bio":"Paus yang hadir pada penobatan Napoleon sebagai Kaisar Prancis dan menghidupkan kembali Serikat Yesus pada 1814.","kisah":"Ia diusir Napoleon dari Negara Gereja selama lima tahun (1809–1814) karena menolak tunduk pada kekuasaan Prancis.","foto":null},{"no":252,"nama":"Paus Leo XII","masa":"1823–1829","lahir":"22 Agustus 1760, Genga, Italia","bio":"Paus yang menyerahkan sistem pendidikan Katolik kepada Yesuit dan mengutuk Freemasonry serta perkumpulan-perkumpulan Alkitab.","kisah":"Ia mengadakan Tahun Yubileum 1825 dan dikenal karena kebijakan konservatifnya.","foto":null},{"no":253,"nama":"Paus Pius VIII","masa":"1829–1830","lahir":"20 November 1761, Cingoli, Italia","bio":"Paus yang hanya memerintah 20 bulan; ia mengutuk perkumpulan rahasia Masonik dan terjemahan Alkitab modernis.","kisah":"Ia menerima Louis Philippe I sebagai Raja Prancis setelah Revolusi Juli 1830.","foto":null},{"no":254,"nama":"Paus Gregorius XVI","masa":"1831–1846","lahir":"18 September 1765, Belluno, Italia","bio":"Seorang rahib Kamaldolese dan Paus non-uskup terakhir yang terpilih; ia menentang reformasi demokratis di Negara Gereja.","kisah":"Pada masa kepausannya, larangan Gereja terhadap heliosentrisme akhirnya dihapus dari Indeks pada 1835.","foto":null},{"no":255,"nama":"Paus Pius IX","masa":"1846–1878","lahir":"13 Mei 1792, Senigallia, Italia","bio":"Beato Pius IX, Paus dengan masa pemerintahan terverifikasi terpanjang (31 tahun); ia menetapkan dogma Dikandung Tanpa Noda (1854) dan infalibilitas Paus (1870).","kisah":"Ia membuka Konsili Vatikan I dan kehilangan Negara Gereja kepada Italia pada 1870.","foto":null},{"no":256,"nama":"Paus Leo XIII","masa":"1878–1903","lahir":"2 Maret 1810, Carpineto Romano, Italia","bio":"Paus yang menerbitkan ensiklik Rerum Novarum (1891) tentang hak-hak pekerja, fondasi ajaran sosial Gereja modern.","kisah":"Ia adalah Paus pertama yang direkam suaranya dan difilmkan dengan kamera film (1898).","foto":null},{"no":257,"nama":"St. Pius X","masa":"1903 – 1914","lahir":"2 Juni 1835, Riese, Italia","bio":"Paus dari keluarga miskin; mendorong komuni yang sering dan komuni pertama anak usia dini.","kisah":"Menolak kemewahan kepausan; ia wafat tak lama setelah Perang Dunia I pecah — hatinya hancur melihat Eropa berperang.","foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/26/Pius_X%2C_by_Ernest_Walter_Histed_%28retouched%29.jpg/960px-Pius_X%2C_by_Ernest_Walter_Histed_%28retouched%29.jpg"},{"no":258,"nama":"Paus Benediktus XV","masa":"1914–1922","lahir":"21 November 1854, Pegli, Genoa, Italia","bio":"Paus yang berupaya tanpa lelah mendamaikan Perang Dunia I dan menerbitkan Kitab Hukum Kanonik 1917.","kisah":"Benediktus XVI mengenangnya sebagai 'nabi perdamaian' karena seruan-seruan damainya selama perang.","foto":null},{"no":259,"nama":"Paus Pius XI","masa":"1922–1939","lahir":"31 Mei 1857, Desio, Italia","bio":"Paus yang menandatangani Perjanjian Lateran (1929) dengan Italia, yang mendirikan Negara Kota Vatikan sebagai negara berdaulat.","kisah":"Ia meresmikan Radio Vatikan (1931) dan menetapkan Pesta Kristus Raja.","foto":null},{"no":260,"nama":"Paus Pius XII","masa":"1939–1958","lahir":"2 Maret 1876, Roma, Italia","bio":"Paus pada masa Perang Dunia II; ia menetapkan dogma Maria Diangkat ke Surga (1950) melalui konstitusi Munificentissimus Deus.","kisah":"Ensiklik Humani generis (1950) adalah dokumen Gereja pertama yang membahas teori evolusi manusia.","foto":null},{"no":261,"nama":"St. Yohanes XXIII","masa":"1958 – 1963","lahir":"25 November 1881, Sotto il Monte, Italia","bio":"Terpilih pada usia 77 tahun dan dianggap \"Paus transisi\", justru menggagas Konsili Vatikan II yang membarui Gereja.","kisah":"Dikenal sebagai \"Paus yang Baik\" — hangat, humoris, dan membuka jendela Gereja kepada dunia modern.","foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Ioannes_XXIII%2C_by_De_Agostini%2C_1958%E2%80%931963.jpg/960px-Ioannes_XXIII%2C_by_De_Agostini%2C_1958%E2%80%931963.jpg"},{"no":262,"nama":"St. Paulus VI","masa":"1963 – 1978","lahir":"26 September 1897, Concesio, Italia","bio":"Melanjutkan dan menutup Konsili Vatikan II; Paus pertama yang bepergian ke luar Italia dengan pesawat dan mengunjungi Tanah Suci.","kisah":"Menerbitkan Humanae Vitae (1968) — keputusan berani yang dipertahankannya meski menuai kontroversi.","foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Pope_Paul_VI_1969_Portrait_%284x5_cropped%29.jpg/960px-Pope_Paul_VI_1969_Portrait_%284x5_cropped%29.jpg"},{"no":263,"nama":"Yohanes Paulus I","masa":"26 Agustus – 28 September 1978 (33 hari)","lahir":"17 Oktober 1912, Canale d'Agordo, Italia","bio":"Memimpin Gereja hanya 33 hari — salah satu masa kepausan tersingkat — namun dikenang karena kerendahan hati dan senyumnya.","kisah":"Paus pertama yang memakai nama ganda (Yohanes Paulus) dan menolak penobatan dengan tiara.","foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Paus_Johannes_Paulus_I_%28Bestanddeelnr_929-9074%29_%28cropped%29.jpg/960px-Paus_Johannes_Paulus_I_%28Bestanddeelnr_929-9074%29_%28cropped%29.jpg"},{"no":264,"nama":"St. Yohanes Paulus II","masa":"1978 – 2005","lahir":"18 Mei 1920, Wadowice, Polandia","bio":"Paus non-Italia pertama setelah 455 tahun; masa kepausan 27 tahun dengan 104 perjalanan apostolik ke 129 negara; berperan besar dalam runtuhnya komunisme di Eropa Timur.","kisah":"Selamat dari percobaan pembunuhan pada 1981; ia mengunjungi dan mengampuni penembaknya di penjara.","foto":"https://upload.wikimedia.org/wikipedia/commons/9/9c/ADAMELLO_-_PAPA_-_Giovanni_Paolo_II_-_panoramio_%28cropped%29.jpg"},{"no":265,"nama":"Benediktus XVI","masa":"2005 – 2013 • Wafat 31 Desember 2022","lahir":"16 April 1927, Marktl, Jerman","bio":"Teolog besar, Prefek Kongregasi Ajaran Iman selama 24 tahun; Paus pertama yang mengundurkan diri dalam hampir 600 tahun.","kisah":"Mengundurkan diri karena merasa tak lagi kuat secara fisik — keputusan rendah hati yang mengejutkan dunia.","foto":"https://upload.wikimedia.org/wikipedia/commons/9/98/Benedykt_XVI_%282010-10-17%29_2.jpg"},{"no":266,"nama":"Fransiskus","masa":"2013 – 2025 • Wafat 21 April 2025","lahir":"17 Desember 1936, Buenos Aires, Argentina","bio":"Paus pertama dari Amerika Selatan dan pertama dari Ordo Yesuit; menekankan Gereja kaum miskin, lingkungan, dan belas kasih.","kisah":"Memilih nama Fransiskus dari Assisi; tinggal di wisma Santa Marta, bukan di Istana Apostolik.","foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Pope_Francis_Korea_Haemi_Castle_19_%284x5_cropped%29.jpg/960px-Pope_Francis_Korea_Haemi_Castle_19_%284x5_cropped%29.jpg"},{"no":267,"nama":"Leo XIV","masa":"8 Mei 2025 – sekarang","lahir":"14 September 1955, Chicago, Amerika Serikat","bio":"Paus pertama dari Amerika Serikat dan dari Ordo Santo Agustinus; lama berkarya sebagai misionaris dan uskup di Peru; terpilih 8 Mei 2025.","kisah":"Menguasai bahasa Inggris, Spanyol, Italia, Prancis, dan Portugis; dikenal sebagai pembangun jembatan di tengah perbedaan.","foto":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Pope_Leo_XIV_3_%283x4_cropped%29.png/960px-Pope_Leo_XIV_3_%283x4_cropped%29.png","aktif":true}];
